# Native Free Exercise DB++ research engine for R.
# Canonical documents are lists; data.frames are explicit research views.
`%||%` <- function(x, y) if (is.null(x)) y else x
.doc <- function(x) if (inherits(x, "fedbpp_document")) unclass(x) else x
.strings <- function(x) as.character(unlist(x %||% character(), use.names=FALSE))
.copy_class <- function(x, cls) structure(x, class=c(cls,"fedbpp_document","list"))
.empty_df <- function(...) data.frame(..., stringsAsFactors=FALSE, check.names=FALSE)
.counted_types <- c("working","backoff","amrap","drop","cluster","rest_pause","assisted")
.counted_set <- function(x) isTRUE(x$completed) && (x$setType %||% "working") %in% .counted_types
.read_json <- function(path) jsonlite::fromJSON(path, simplifyVector=FALSE, simplifyDataFrame=FALSE, simplifyMatrix=FALSE)
.json_array_key <- function(k) !is.null(k) && (grepl("(Ids|Offsets|Weekdays|Prescriptions|Exercises|Families|Patterns|Codes|Information|Goals|SchemaVersions|SetTypes|Substitutions)$",k) || k %in% c("sessions","direct","indirect","stabilizers","reasonCodes","warnings","defaultsApplied","missingInformation","conflicts","equipmentAdded","equipmentRemoved","preferredExerciseIds","avoidedExerciseIds","requiredExerciseIds","lockedExerciseIds","requiredFamilyIds","excludedFamilyIds","preferredFamilyIds","avoidedFamilyIds","preferredExercisesUsed","preferredFamiliesUsed","avoidedExercisesUsed","avoidedFamiliesUsed"))
.json_prepare <- function(x,key=NULL) { if(is.atomic(x)&&length(x)>1L)return(as.list(x));if(is.atomic(x)&&length(x)==1L&&.json_array_key(key))return(I(x));if(is.list(x)){if(!length(x)&&!is.null(names(x)))return(x);if(!is.null(names(x))&&length(x))return(setNames(lapply(names(x),function(k).json_prepare(x[[k]],k)),names(x)));return(lapply(x,.json_prepare))};x }
.write_json <- function(x,path=NULL,pretty=TRUE) { z <- paste0(as.character(jsonlite::toJSON(.json_prepare(x),auto_unbox=TRUE,null="null",dataframe="rows",pretty=pretty,na="null",digits=15,force=TRUE)),"\n"); if(is.null(path)) z else {writeLines(z,path,useBytes=TRUE); invisible(path)} }
.resource <- function(name) { p <- system.file("extdata",name,package="fedbpp"); if(nzchar(p)&&file.exists(p)) return(p); q <- c(file.path("inst","extdata",name),file.path("packages","r","fedbpp","inst","extdata",name),name); q <- q[file.exists(q)]; if(!length(q)) stop("bundled resource is unavailable: ",name); q[[1L]] }
.range <- function(x,keys=c("min","target","max")) { if(is.numeric(x)&&length(x)==1L&&!is.na(x)) return(setNames(rep(as.numeric(x),3L),keys)); if(is.numeric(x)&&length(x)==length(keys)&&!is.null(names(x))&&all(keys%in%names(x))) return(as.list(x[keys])); if(is.null(x)) return(setNames(list(NULL,NULL,NULL),keys)); if(!is.list(x)) return(setNames(list(NULL,NULL,NULL),keys)); setNames(lapply(keys,function(k) if(is.null(x[[k]])) NULL else as.numeric(x[[k]])),keys) }
.scalar <- function(x) { z <- .range(x)[c("target","min","max")]; z <- z[!vapply(z,is.null,logical(1))]; if(length(z)) as.numeric(z[[1L]]) else 0 }
.add_range <- function(a,b) { a <- .range(a); b <- .range(b); setNames(lapply(names(a),function(k) if(is.null(a[[k]])||is.null(b[[k]])) NULL else round(a[[k]]+b[[k]],6)),names(a)) }
.scale_range <- function(x,k) { x <- .range(x); setNames(lapply(x,function(v) if(is.null(v)) NULL else round(v*k,6)),names(x)) }
.range_clean <- function(x) { x <- .range(x); setNames(lapply(x,function(v) if(is.null(v)) NULL else round(v,6)),names(x)) }
.range_state <- function(actual,target) { r <- .range(target); if(!is.null(r$min)&&actual<r$min) return("below_minimum"); if(!is.null(r$max)&&actual>r$max) return("above_maximum"); if(is.null(r$target)) return("within_range"); if(actual==r$target) "at_target" else if(actual<r$target) "within_range_below_target" else "within_range_above_target" }
.range_errors <- function(r,field) { if(!is.list(r)) return(character()); e <- character(); if(!is.null(r$min)&&!is.null(r$max)&&r$min>r$max)e<-c(e,paste0(field,": min must not exceed max")); if(!is.null(r$target)&&!is.null(r$min)&&r$target<r$min)e<-c(e,paste0(field,": target must not be below min")); if(!is.null(r$target)&&!is.null(r$max)&&r$target>r$max)e<-c(e,paste0(field,": target must not exceed max")); e }
.set_credits <- function(db) { credits <- (db$metadata %||% list())$setCredits; if(!is.list(credits)||!all(c("direct","indirect","stabilizer")%in%names(credits))) stop("database metadata.setCredits must define direct, indirect, and stabilizer"); z<-vapply(c("direct","indirect","stabilizer"),function(k)as.numeric(credits[[k]]),numeric(1)); if(any(!is.finite(z))||any(z<0))stop("database metadata.setCredits must be finite and non-negative"); z }
.exercise <- function(db,id) if(!is.null(id)&&length(id)&&!is.null(db$exercises[[id]])) db$exercises[[id]] else NULL
.annotation <- function(ex) ex$annotation %||% list()
.credit_role <- function(role) if (role == "stabilizers") "stabilizer" else role
.parse_time <- function(x,timezone="UTC") { if(inherits(x,"POSIXt"))return(as.POSIXct(x,tz="UTC")); if(is.null(x)||!nzchar(as.character(x)))return(as.POSIXct(NA,origin="1970-01-01",tz="UTC")); s<-sub("Z$","+0000",as.character(x)); s<-sub("([+-][0-9]{2}):([0-9]{2})$","\\1\\2",s); z<-as.POSIXct(s,format="%Y-%m-%dT%H:%M:%OS%z",tz="UTC"); if(is.na(z))z<-as.POSIXct(s,format="%Y-%m-%dT%H:%M:%z",tz="UTC"); if(is.na(z)&&!grepl("[+-][0-9]{4}$",s))z<-as.POSIXct(s,format="%Y-%m-%dT%H:%M:%OS",tz=timezone); z }

load_database <- function(path=NULL) { d<-.read_json(path %||% .resource("free-exercise-db-plusplus.json")); if(!is.list(d$exercises))stop("database is missing exercises"); .copy_class(d,"fedbpp_database") }
load_relationships <- function(path=NULL,db=NULL) { d<-.read_json(path %||% .resource("exercise-relationships.json")); if(!is.list(d$families)||!is.list(d$relationships))stop("relationship artifact is missing families or relationships"); d$.by_exercise<-list();d$.by_family<-list();for(r in d$relationships){if(identical(r$relationship,"member_of_family"))d$.by_family[[r$familyId]]<-c(d$.by_family[[r$familyId]]%||%character(),r$sourceExerciseId);d$.by_exercise[[r$sourceExerciseId]]<-c(d$.by_exercise[[r$sourceExerciseId]]%||%list(),list(r))};d$.by_family<-lapply(d$.by_family,function(x)sort(unique(x)));.copy_class(d,"fedbpp_relationships") }
family_for <- function(relationships,exercise_id){ if(is.null(relationships)||is.null(exercise_id)||!length(exercise_id))return(NULL); rows<-Filter(function(x)identical(x$relationship,"member_of_family"),relationships$.by_exercise[[exercise_id]]%||%list());if(length(rows))relationships$families[[rows[[1L]]$familyId]] else NULL }
family_members <- function(relationships,family_id) relationships$.by_family[[family_id]]%||%character()
related_exercises <- function(relationships,exercise_id,same_family=TRUE){f<-family_for(relationships,exercise_id);if(same_family&&!is.null(f))return(setdiff(family_members(relationships,f$familyId),exercise_id));sort(.strings(vapply(relationships$.by_exercise[[exercise_id]]%||%list(),function(x)x$targetExerciseId%||%"",character(1))))}

read_workout <- function(path,validate=TRUE){x<-.read_json(path);if(validate)validate_workout(x);.copy_class(x,"fedbpp_workout")}; load_workout<-read_workout
write_workout <- function(workout,path=NULL,pretty=TRUE).write_json(.doc(workout),path,pretty)
validate_workout <- function(workout){if(!is.list(workout))return("<root>: must be an object");req<-c("schemaVersion","sessionId","startTime","exercises");missing<-req[!(req%in%names(workout))];e<-if(length(missing))paste0(missing,": is required")else character();if(!is.null(workout$schemaVersion)&&!workout$schemaVersion%in%c("0.2.0","0.3.0"))e<-c(e,"schemaVersion: unsupported");if(!is.null(workout$exercises)&&!is.list(workout$exercises))e<-c(e,"exercises: must be an array");if(length(e))stop(paste(sort(unique(e)),collapse="; "));invisible(TRUE)}
migrate_workout <- function(workout){if(workout$schemaVersion%in%c("0.2.0","0.3.0"))return(workout);if(!startsWith(workout$schemaVersion%||%"","0.1."))stop("unsupported workout schema");workout$schemaVersion<-"0.2.0";workout}

read_workout_plan <- function(path,validate=TRUE){x<-.read_json(path);if(validate){e<-validate_plan(x);if(length(e))stop(paste(e,collapse="; "))};.copy_class(x,"fedbpp_workout_plan")};write_workout_plan<-function(plan,path=NULL,pretty=TRUE).write_json(.doc(plan),path,pretty)
read_volume_target <- function(path,validate=TRUE){x<-.read_json(path);if(validate){e<-validate_target(x);if(length(e))stop(paste(e,collapse="; "))};.copy_class(x,"fedbpp_volume_target")};write_volume_target<-function(target,path=NULL,pretty=TRUE).write_json(.doc(target),path,pretty)
read_training_profile <- function(path,validate=TRUE){x<-.read_json(path);if(validate){e<-validate_training_profile(x);if(length(e))stop(paste(e,collapse="; "))};.copy_class(x,"fedbpp_training_profile")};write_training_profile<-function(profile,path=NULL,pretty=TRUE).write_json(.doc(profile),path,pretty)
read_workout_intent <- function(path,validate=TRUE){x<-.read_json(path);if(validate){e<-validate_workout_intent(x);if(length(e))stop(paste(e,collapse="; "))};.copy_class(x,"fedbpp_workout_intent")};write_workout_intent<-function(intent,path=NULL,pretty=TRUE).write_json(.doc(intent),path,pretty)
read_training_history <- function(path,validate=TRUE){x<-.read_json(path);if(validate){e<-validate_training_history(x);if(length(e))stop(paste(e,collapse="; "))};.copy_class(x,"fedbpp_training_history")};write_training_history<-function(history,path=NULL,pretty=TRUE).write_json(.doc(history),path,pretty)

validate_training_history<-function(history){if(!is.list(history))return("<root>: must be an object");if(is.null(history$subjectId)||!nzchar(history$subjectId))return("subjectId: is required");character()}
validate_training_profile<-function(profile,db=NULL,relationships=NULL){if(!is.list(profile))return("<root>: must be an object");e<-character();if(!identical(profile$schemaVersion,"0.1.0"))e<-c(e,"schemaVersion: must be 0.1.0");if(is.null(profile$profileId)||!nzchar(profile$profileId))e<-c(e,"profileId: is required");av<-profile$availability%||%list();for(k in c("sessionsPerCycle","minutesPerSession","exercisesPerSession"))e<-c(e,.range_errors(av[[k]],paste0("availability.",k)));if(!is.null(av$cycleLengthDays)&&any(c(av$preferredDayOffsets%||%integer(),av$excludedDayOffsets%||%integer())>=av$cycleLengthDays))e<-c(e,"availability day offsets must be within cycleLengthDays");e}
validate_plan<-function(plan){if(!is.list(plan))return("<root>: must be an object");e<-character();for(k in c("schemaVersion","planId","revisionId","name","cycle","sessions"))if(is.null(plan[[k]]))e<-c(e,paste0(k,": is required"));ids<-character();sids<-character();for(i in seq_along(plan$sessions%||%list())){s<-plan$sessions[[i]];if(s$planSessionId%in%sids)e<-c(e,"duplicate planSessionId");sids<-c(sids,s$planSessionId);for(j in seq_along(s$exercises%||%list())){r<-s$exercises[[j]];if(r$prescriptionId%in%ids)e<-c(e,"duplicate prescriptionId");ids<-c(ids,r$prescriptionId);e<-c(e,.range_errors(r$sets,paste0("sessions[",i,"].exercises[",j,"].sets")),.range_errors(r$reps,paste0("sessions[",i,"].exercises[",j,"].reps")))}};sort(unique(unlist(e)[nzchar(unlist(e))]))}

effective_sets<-function(workout,database){w<-.doc(workout);validate_workout(w);cr<-.set_credits(database);rows<-list();for(ob in w$exercises%||%list()){ex<-.exercise(database,ob$exerciseId);if(is.null(ex))next;a<-.annotation(ex);if(!isTRUE(a$volumeEligible))next;n<-sum(vapply(ob$sets%||%list(),.counted_set,logical(1)));for(role in c("direct","indirect","stabilizers"))for(m in .strings(a[[role]]))rows[[length(rows)+1L]]<-data.frame(muscle=m,effective_sets=n*cr[[.credit_role(role)]],credit=cr[[.credit_role(role)]],exercise_id=ob$exerciseId,confidence=a$confidence%||%NA_character_,stringsAsFactors=FALSE)};if(length(rows))do.call(rbind,rows) else .empty_df(muscle=character(),effective_sets=numeric(),credit=numeric(),exercise_id=character(),confidence=character())}
workout_observations<-function(workout){w<-.doc(workout);validate_workout(w);r<-lapply(w$exercises%||%list(),function(e)data.frame(session_id=w$sessionId,start_time=w$startTime,exercise_id=e$exerciseId%||%NA_character_,exercise_name=e$exerciseName%||%NA_character_,order=as.integer(e$order%||%NA_integer_),set_count=length(e$sets%||%list()),completed_set_count=sum(vapply(e$sets%||%list(),.counted_set,logical(1))),stringsAsFactors=FALSE));if(length(r))do.call(rbind,r) else .empty_df(session_id=character(),start_time=character(),exercise_id=character(),exercise_name=character(),order=integer(),set_count=integer(),completed_set_count=integer())}

.coverage<-function(plan,db){cr<-.set_credits(db);direct<-indirect<-stabilizer<-patterns<-list();planned<-mapped<-unmapped<-ineligible<-.range(0);unmapped_ids<-ineligible_ids<-character();exp_m<-exp_p<-list();add<-function(x,k,v){x[[k]]<-.add_range(x[[k]]%||%.range(0),v);x};for(s in plan$sessions%||%list())for(rx in s$exercises%||%list()){v<-if(!is.null(rx$plannedSets)) .range(sum(vapply(rx$plannedSets,function(ps).counted_set(ps),logical(1)))) else if(!is.null(rx$setType)&&!rx$setType%in%.counted_types) .range(0) else .range(rx$sets%||%0);planned<-.add_range(planned,v);ex<-.exercise(db,rx$exerciseId);if(is.null(ex)){unmapped<-.add_range(unmapped,v);unmapped_ids<-c(unmapped_ids,rx$prescriptionId);next};mapped<-.add_range(mapped,v);a<-.annotation(ex);if(!isTRUE(a$volumeEligible)){ineligible<-.add_range(ineligible,v);ineligible_ids<-c(ineligible_ids,rx$prescriptionId);next};for(m in .strings(a$direct)){direct<-add(direct,m,v);exp_m[[m]]<-unique(c(exp_m[[m]]%||%character(),s$planSessionId))};for(m in .strings(a$indirect)){indirect<-add(indirect,m,v);exp_m[[m]]<-unique(c(exp_m[[m]]%||%character(),s$planSessionId))};for(m in .strings(a$stabilizers))stabilizer<-add(stabilizer,m,v);for(p in .strings(a$patterns)){patterns<-add(patterns,p,v);exp_p[[p]]<-unique(c(exp_p[[p]]%||%character(),s$planSessionId))}};muscles<-sort(unique(c(names(direct),names(indirect),names(stabilizer))));effective<-list();for(m in muscles)effective[[m]]<-.add_range(.add_range(.scale_range(direct[[m]]%||%.range(0),cr[["direct"]]),.scale_range(indirect[[m]]%||%.range(0),cr[["indirect"]])),.scale_range(stabilizer[[m]]%||%.range(0),cr[["stabilizer"]]));view<-function(k=1){ds<-lapply(direct,.scale_range,k=k);is<-lapply(indirect,.scale_range,k=k);ss<-lapply(stabilizer,.scale_range,k=k);es<-lapply(effective,.scale_range,k=k);clean<-function(x){x<-x[vapply(x,function(z)any(!vapply(z,function(v)is.null(v)||v==0,logical(1))),logical(1))];lapply(x,.range_clean)};o<-list(directSetRanges=clean(ds),indirectSetRanges=clean(is),stabilizerParticipationSetRanges=clean(ss),effectiveSetRanges=clean(es),movementPatternSetRanges=clean(lapply(patterns,.scale_range,k=k)));for(z in c("direct","indirect","stabilizerParticipation","effective","movementPattern"))o[[paste0(z,"Sets")]]<-lapply(o[[paste0(z,"SetRanges")]],.scalar);o};ps<-.scalar(planned);ms<-.scalar(mapped);list(coverageCompleteness=list(plannedSets=ps,plannedSetRange=.range_clean(planned),mappedSets=ms,mappedSetRange=.range_clean(mapped),unmappedSets=.scalar(unmapped),unmappedSetRange=.range_clean(unmapped),ineligibleSets=.scalar(ineligible),ineligibleSetRange=.range_clean(ineligible),mappedFraction=if(ps)round(ms/ps,6) else 1,unmappedPrescriptions=sort(unique(unmapped_ids[nzchar(unmapped_ids)])),ineligiblePrescriptions=sort(unique(ineligible_ids[nzchar(ineligible_ids)]))),nativeCycle=list(periodDays=plan$cycle$lengthDays,view(),exposureFrequency=list(muscles=lapply(exp_m,function(x)list(exposuresPerNativeCycle=length(x),normalizedExposuresPer7Days=round(length(x)*7/plan$cycle$lengthDays,6))),movementPatterns=lapply(exp_p,function(x)list(exposuresPerNativeCycle=length(x),normalizedExposuresPer7Days=round(length(x)*7/plan$cycle$lengthDays,6))))),cr=cr)}
analyze_plan<-function(plan,database){p<-.doc(plan);x<-.coverage(p,database);md<-database$metadata%||%list();prov<-list(analysisVersion="1.0.0",analysisPolicy="dbpp-default-volume-v1",dbSchemaVersion=md$schemaVersion%||%NULL,dbConverterVersion=md$converterVersion%||%NULL,dbUpstreamSha256=(md$upstream%||%list())$sha256%||%NULL,planSchemaVersion=p$schemaVersion%||%NULL,setCredits=x$cr,nativePeriodDays=p$cycle$lengthDays,normalizedPeriodDays=7,rangePolicy="target-then-min-then-max",unitPolicy="dbpp-conservative-units-v1");n<-x$nativeCycle;norm<-n;norm$periodDays<-7;f<-7/p$cycle$lengthDays;for(k in c("directSetRanges","indirectSetRanges","stabilizerParticipationSetRanges","effectiveSetRanges","movementPatternSetRanges")){norm[[k]]<-lapply(n[[k]],.scale_range,k=f);norm[[sub("Ranges$","s",k)]]<-lapply(norm[[k]],.scalar)};list(analysisVersion="1.0.0",analysisPolicy="dbpp-default-volume-v1",plan=list(planId=p$planId,revisionId=p$revisionId),analysisMetadata=prov,coverageCompleteness=x$coverageCompleteness,nativeCycle=n,normalized7Day=norm,exposureFrequency=x$nativeCycle$exposureFrequency)}

merge_target<-function(default,explicit=NULL){if(is.null(explicit))return(default);out<-default;section<-function(a,b){a<-a%||%list();for(k in names(b%||%list()))a[[k]]<-if(is.list(a[[k]])&&is.list(b[[k]]))modifyList(a[[k]],b[[k]]) else b[[k]];a};for(k in names(explicit)){if(k%in%c("muscles","movementPatterns","families"))out[[k]]<-section(out[[k]],explicit[[k]]) else if(k=="frequency"){out$frequency<-out$frequency%||%list();out$frequency$muscles<-section(out$frequency$muscles,explicit[[k]]$muscles)}else out[[k]]<-explicit[[k]]};out}
 .target_range_errors <- function(r, field) {
  z <- .range_errors(r, field)
  gsub("\\bmin\\b", "minimum", gsub("\\bmax\\b", "maximum", z))
 }
validate_target<-function(target,db=NULL,relationships=NULL){if(!is.list(target))return("<root>: must be an object");e<-character();for(k in c("schemaVersion","targetId","periodDays","muscles"))if(is.null(target[[k]]))e<-c(e,paste0(k,": is required"));for(z in list(c("muscles","min","target","max"),c("movementPatterns","minimumSets","targetSets","maximumSets"),c("families","minimumSets","targetSets","maximumSets")))for(k in names(target[[z[[1L]]]]%||%list()))e<-c(e,.target_range_errors(target[[z[[1L]]]][[k]],paste0(z[[1L]],".",k)));for(k in names((target$frequency%||%list())$muscles%||%list()))e<-c(e,.target_range_errors(target$frequency$muscles[[k]],paste0("frequency.muscles.",k)));sort(unique(e[nzchar(e)]))}
read_intent_policies<-function().read_json(.resource("intent-policies.json"))
validate_workout_intent<-function(intent,database=NULL,relationships=NULL){if(!is.list(intent))return("<root>: must be an object");allowed<-c("schemaVersion","intentId","subjectId","goal","schedule","sessionConstraints","environment","equipmentOverrides","exerciseConstraints","preferences","continuity","useHistory","historyWindow","requestedPlanningPolicy","requestedGoalPolicy");e<-if(length(setdiff(names(intent),allowed)))paste0("<root>: additional property ",setdiff(names(intent),allowed))else character();if(!identical(intent$schemaVersion,"0.1.0"))e<-c(e,"schemaVersion: must be 0.1.0");s<-intent$schedule%||%list();if(length(c(s$preferredWeekdays%||%character(),s$excludedWeekdays%||%character()))&&s$cycleLengthDays!=7)e<-c(e,"schedule weekday fields require cycleLengthDays of 7");if(length(intersect(.strings(s$preferredWeekdays),.strings(s$excludedWeekdays))))e<-c(e,"schedule: preferredWeekdays and excludedWeekdays conflict");if(length(intersect(s$preferredDayOffsets%||%integer(),s$excludedDayOffsets%||%integer())))e<-c(e,"schedule: preferredDayOffsets and excludedDayOffsets conflict");e<-c(e,.range_errors(s$sessionsPerCycle,"schedule.sessionsPerCycle"),.range_errors((intent$sessionConstraints%||%list())$exercisesPerSession,"sessionConstraints.exercisesPerSession"));cst<-intent$exerciseConstraints%||%list();p<-intent$preferences%||%list();if(length(intersect(c(.strings(cst$requiredExerciseIds),.strings(cst$lockedExerciseIds)),.strings(cst$excludedExerciseIds))))e<-c(e,"exerciseConstraints: requiredExerciseIds conflicts with excludedExerciseIds");if(length(intersect(.strings(cst$requiredFamilyIds),.strings(cst$excludedFamilyIds))))e<-c(e,"exerciseConstraints: requiredFamilyIds conflicts with excludedFamilyIds");if(length(c(.strings(cst$requiredFamilyIds),.strings(cst$excludedFamilyIds),.strings(p$preferredFamilyIds),.strings(p$avoidedFamilyIds)))&&is.null(relationships))e<-c(e,"exercise family constraints require exercise relationships");if(identical(intent$goal,"hypertrophy")&&identical(intent$requestedGoalPolicy,"general-strength-v1")||identical(intent$goal,"strength")&&identical(intent$requestedGoalPolicy,"general-hypertrophy-v1"))e<-c(e,"GOAL_POLICY_MISMATCH");if(!is.null(database)){known<-names(database$exercises);for(k in c("requiredExerciseIds","lockedExerciseIds","excludedExerciseIds"))if(length(setdiff(.strings(cst[[k]]),known)))e<-c(e,paste0(k,": unknown exerciseId: ",setdiff(.strings(cst[[k]]),known)));for(k in c("preferredExerciseIds","avoidedExerciseIds"))if(length(setdiff(.strings(p[[k]]),known)))e<-c(e,paste0(k,": unknown exerciseId: ",setdiff(.strings(p[[k]]),known)))};sort(unique(e[nzchar(e)]))}
resolve_intent<-function(intent,db=NULL,profile=NULL,target=NULL,relationships=NULL,history=NULL,as_of=NULL){i<-.doc(intent);supplied<-!is.null(profile);profile<-profile%||%list();errors<-validate_workout_intent(i,db,relationships);empty<-list(status="invalid",resolvedProfile=NULL,resolvedTarget=NULL,planningPolicy=NULL,goalPolicy=NULL,environmentPolicy=NULL,generationOptions=list(),missingInformation=list(),warnings=character(),conflicts=list(),defaultsApplied=character(),explicitOverrides=list(goalPolicy=FALSE,planningPolicy=FALSE,target=!is.null(target),trainingProfile=supplied,equipmentAdded=character(),equipmentRemoved=character()),provenance=list(intentSchemaVersion=i$schemaVersion%||%NULL));if(length(errors)){empty$conflicts<-lapply(errors,function(x)list(code=if(x=="GOAL_POLICY_MISMATCH")x else "INVALID_INTENT",detail=x));return(empty)};s<-i$schedule%||%list();missing<-list();if(is.null(i$goal))missing<-c(missing,list(list(field="goal",reason="required_for_goal_policy_resolution")));if(is.null(s$cycleLengthDays))missing<-c(missing,list(list(field="schedule.cycleLengthDays",reason="required_for_schedule_resolution")));if(is.null(s$sessionsPerCycle))missing<-c(missing,list(list(field="schedule.sessionsPerCycle",reason="required_for_schedule_resolution")));if(is.null(i$environment)&&!length(profile$equipment))missing<-c(missing,list(list(field="environmentOrEquipment",reason="required_for_equipment_resolution")));if(length(missing)){empty$status<-"needs_clarification";empty$missingInformation<-missing;return(empty)};pol<-read_intent_policies();gid<-i$requestedGoalPolicy%||%switch(i$goal,hypertrophy="general-hypertrophy-v1",strength="general-strength-v1",NULL);gp<-pol$goalPolicies[[gid]];if(is.null(gp)||!identical(gp$goal,i$goal)){empty$conflicts<-list(list(code="GOAL_POLICY_MISMATCH",goal=i$goal,requestedGoalPolicy=gid,policyGoal=gp$goal%||%NULL));return(empty)};env_id<-names(pol$environmentPolicies)[vapply(pol$environmentPolicies,function(x)identical(x$environment,i$environment),logical(1))];env<-if(length(env_id))pol$environmentPolicies[[env_id[[1L]]]]else NULL;eo<-i$equipmentOverrides%||%list();additions<-sort(unique(.strings(eo$addEquipment)));removals<-sort(unique(.strings(eo$removeEquipment)));equip<-if(length(profile$equipment)) .strings(profile$equipment) else .strings(env$equipment);equip<-sort(setdiff(unique(c(equip,additions)),removals));profile$schemaVersion<-profile$schemaVersion%||%"0.1.0";profile$profileId<-profile$profileId%||%"resolved-profile";profile$subjectId<-i$subjectId%||%profile$subjectId%||%NULL;profile$goals<-list(list(type=i$goal));profile$equipment<-equip;av<-profile$availability%||%list();av$cycleLengthDays<-s$cycleLengthDays;av$sessionsPerCycle<-s$sessionsPerCycle;wd<-c("monday","tuesday","wednesday","thursday","friday","saturday","sunday");av$preferredDayOffsets<-sort(unique(c(as.integer(s$preferredDayOffsets%||%integer()),match(s$preferredWeekdays%||%character(),wd)-1L)));av$preferredDayOffsets<-av$preferredDayOffsets[!is.na(av$preferredDayOffsets)];av$excludedDayOffsets<-sort(unique(c(as.integer(s$excludedDayOffsets%||%integer()),match(s$excludedWeekdays%||%character(),wd)-1L)));av$excludedDayOffsets<-av$excludedDayOffsets[!is.na(av$excludedDayOffsets)];if(!is.null(i$sessionConstraints$exercisesPerSession))av$exercisesPerSession<-i$sessionConstraints$exercisesPerSession;profile$availability<-av;profile$constraints<-profile$constraints%||%list();cst<-i$exerciseConstraints%||%list();profile$constraints$excludedExerciseIds<-sort(unique(c(.strings(profile$constraints$excludedExerciseIds),.strings(cst$excludedExerciseIds))));profile$constraints$excludedFamilyIds<-sort(unique(c(.strings(profile$constraints$excludedFamilyIds),.strings(cst$excludedFamilyIds))));profile$exercisePreferences<-profile$exercisePreferences%||%list();p<-i$preferences%||%list();for(k in c("preferredExerciseIds","avoidedExerciseIds","preferredFamilyIds","avoidedFamilyIds"))if(length(p[[k]]))profile$exercisePreferences[[k]]<-sort(unique(c(.strings(profile$exercisePreferences[[k]]),.strings(p[[k]]))));rt<-merge_target(list(schemaVersion="0.1.0",targetId=paste0(gid,"-default"),periodDays=s$cycleLengthDays,muscles=gp$muscles,notes=gp$description),target);te<-validate_target(rt,db,relationships);if(length(te)){empty$resolvedTarget<-rt;empty$conflicts<-lapply(te,function(x)list(code="TARGET_OVERRIDE_CONFLICT",detail=x));return(empty)};defaults<-c(if(is.null(i$requestedGoalPolicy))"goalPolicy",if(is.null(i$requestedPlanningPolicy))"planningPolicy",if(!is.null(env))"environmentPolicy");opts<-list(continuity=i$continuity%||%"neutral",repDefaults=gp$reps,effortDefaults=gp$effort,requiredFamilyIds=sort(.strings(cst$requiredFamilyIds)));warnings<-character();if(isTRUE(i$useHistory)&&is.null(history))warnings<-c(warnings,"useHistory was requested but no history was provided");if(isTRUE(i$useHistory)&&!is.null(history)&&is.null(as_of))warnings<-c(warnings,"useHistory was requested but as_of is required to derive TrainingState");if(isTRUE(i$useHistory)&&!is.null(history)&&!is.null(as_of))opts$trainingState<-derive_training_state(history,db,as_of=as_of,window=i$historyWindow%||%"last_28_days",relationships=relationships,target=rt);list(status=if(length(defaults))"resolved_with_defaults"else"resolved",resolvedProfile=profile,resolvedTarget=rt,planningPolicy=i$requestedPlanningPolicy%||%gp$planningPolicy,goalPolicy=list(policyId=gid,policyVersion=gp$policyVersion,description=gp$description),environmentPolicy=if(length(env_id))env$policyId else NULL,generationOptions=opts,missingInformation=list(),warnings=warnings,conflicts=list(),defaultsApplied=defaults,explicitOverrides=list(goalPolicy=!is.null(i$requestedGoalPolicy),planningPolicy=!is.null(i$requestedPlanningPolicy),target=!is.null(target),trainingProfile=supplied,equipmentAdded=additions,equipmentRemoved=removals),provenance=list(intentSchemaVersion=i$schemaVersion,goalPolicy=list(policyId=gid,policyVersion=gp$policyVersion),environmentPolicy=if(length(env_id))list(policyId=env$policyId,policyVersion=gp$policyVersion) else NULL,dbSchemaVersion=db$metadata$schemaVersion%||%NULL,dbConverterVersion=db$metadata$converterVersion%||%NULL,relationshipSchemaVersion=relationships$schemaVersion%||%NULL))}

compare_to_targets<-function(plan,target,db){a<-analyze_plan(plan,db);f<-target$periodDays/a$analysisMetadata$nativePeriodDays;eff<-a$nativeCycle$effectiveSets;rg<-a$nativeCycle$effectiveSetRanges;rows<-list();for(m in sort(unique(c(names(target$muscles%||%list()),names(eff))))){tr<-target$muscles[[m]];r<-.range(tr);actual<-round((eff[[m]]%||%0)*f,6);rows[[m]]<-list(actualEffectiveSets=actual,minimum=r$min,target=r$target,maximum=r$max,min=r$min,max=r$max,differenceFromTarget=if(is.null(r$target))NULL else round(actual-r$target,6),planEffectiveSetRange=.range_clean(.scale_range(rg[[m]]%||%.range(0),f)),state=if(is.null(tr))"not_targeted"else .range_state(actual,r),periodDays=target$periodDays)};list(analysisVersion="0.1.0",plan=a$plan,target=list(targetId=target$targetId,periodDays=target$periodDays),analysisPolicy=a$analysisPolicy,analysisMetadata=c(a$analysisMetadata,list(targetSchemaVersion=target$schemaVersion,comparisonPeriodDays=target$periodDays)),coverageCompleteness=a$coverageCompleteness,muscles=rows)}
.family_coverage<-function(plan,rel){out<-list();for(s in plan$sessions%||%list())for(rx in s$exercises%||%list()){f<-family_for(rel,rx$exerciseId);if(is.null(f))next;id<-f$familyId;z<-out[[id]]%||%list(familyId=id,name=f$name,exerciseIds=character(),plannedSetRanges=.range(0),sessions=character(),variantDimensions=list());z$exerciseIds<-sort(unique(c(z$exerciseIds,rx$exerciseId)));z$plannedSetRanges<-.add_range(z$plannedSetRanges,.range(if(!is.null(rx$plannedSets))sum(vapply(rx$plannedSets,.counted_set,logical(1))) else rx$sets%||%0));z$sessions<-sort(unique(c(z$sessions,s$planSessionId)));out[[id]]<-z};for(id in names(out)){out[[id]]$plannedSets<-.scalar(out[[id]]$plannedSetRanges);out[[id]]$sessionExposures<-length(out[[id]]$sessions)};out}

evaluate_plan<-function(plan,db,profile=NULL,target=NULL,relationships=NULL){
  p<-.doc(plan);a<-analyze_plan(p,db);profile<-.doc(profile);target<-.doc(target)
  muscles<-if(!is.null(target))compare_to_targets(p,target,db)$muscles else list();frequency<-list();patterns<-list();families<-list()
  if(!is.null(target))for(m in sort(names((target$frequency%||%list())$muscles%||%list()))){r<-.range(target$frequency$muscles[[m]]);x<-a$exposureFrequency$muscles[[m]]%||%list(exposuresPerNativeCycle=0,normalizedExposuresPer7Days=0);frequency[[m]]<-list(plannedExposuresPerNativeCycle=x$exposuresPerNativeCycle,normalizedExposuresPer7Days=x$normalizedExposuresPer7Days,minimum=r$min,target=r$target,maximum=r$max,state=.range_state(x$normalizedExposuresPer7Days,r))}
  if(!is.null(target))for(m in sort(names(target$movementPatterns%||%list()))){r<-.range(target$movementPatterns[[m]],c("min","target","max"));x<-a$nativeCycle$movementPatternSets[[m]]%||%0;patterns[[m]]<-list(plannedSets=x,minimum=r$min,target=r$target,maximum=r$max,state=.range_state(x,r))}
  fc<-if(!is.null(relationships)).family_coverage(p,relationships)else list(available=FALSE,reason="relationship artifact not provided")
  if(!is.null(target)&&!is.null(relationships))for(m in sort(names(target$families%||%list()))){r<-.range(target$families[[m]],c("minimumSets","targetSets","maximumSets"));x<-fc[[m]]$plannedSets%||%0;families[[m]]<-list(plannedSets=x,minimum=r$min,target=r$target,maximum=r$max,state=.range_state(x,r))}
  hard<-list();supported<-character();unsupported<-list();unknown<-list()
  if(!is.null(profile)){av<-.strings(profile$equipment);body<-c("body only","bodyweight","no equipment","none");cst<-profile$constraints%||%list();for(s in p$sessions%||%list())for(rx in s$exercises%||%list()){ex<-.exercise(db,rx$exerciseId);f<-family_for(relationships,rx$exerciseId);fid<-if(!is.null(f))f$familyId else NULL;if(length(rx$exerciseId)&&rx$exerciseId%in%.strings(cst$excludedExerciseIds))hard[[length(hard)+1L]]<-list(type="excluded_exercise",exerciseId=rx$exerciseId,prescriptionId=rx$prescriptionId,sessionId=s$planSessionId);if(!is.null(fid)&&fid%in%.strings(cst$excludedFamilyIds))hard[[length(hard)+1L]]<-list(type="excluded_family",exerciseId=rx$exerciseId,familyId=fid,prescriptionId=rx$prescriptionId,sessionId=s$planSessionId);if(is.null(ex))unknown[[length(unknown)+1L]]<-list(type="unknown_exercise",exerciseId=rx$exerciseId,prescriptionId=rx$prescriptionId,sessionId=s$planSessionId)else{eq<-ex$source$equipment%||%NULL;if(is.null(eq)||eq=="other")unknown[[length(unknown)+1L]]<-list(type="unknown_equipment",exerciseId=rx$exerciseId,prescriptionId=rx$prescriptionId,sessionId=s$planSessionId)else if(eq%in%av||(eq%in%body&&length(intersect(av,body))))supported<-c(supported,rx$exerciseId)else{z<-list(type="unsupported_equipment",equipment=eq,exerciseId=rx$exerciseId,prescriptionId=rx$prescriptionId,sessionId=s$planSessionId);unsupported[[length(unsupported)+1L]]<-z;hard[[length(hard)+1L]]<-z}}};equipment<-list(supportedExercises=sort(unique(supported)),unsupportedExercises=unsupported,unknownEquipmentExercises=unknown)}else equipment<-list(findings=list())
  av<-list(plannedSessions=length(p$sessions%||%list()),state="not_evaluated");if(!is.null(profile$availability)){r<-.range(profile$availability$sessionsPerCycle);av<-list(plannedSessions=length(p$sessions%||%list()),min=r$min,target=r$target,max=r$max,state=.range_state(length(p$sessions%||%list()),r));for(s in p$sessions%||%list())if(s$dayOffset%in%(profile$availability$excludedDayOffsets%||%integer()))hard[[length(hard)+1L]]<-list(type="excluded_day_offset",sessionId=s$planSessionId,dayOffset=s$dayOffset)}
  counts<-list();if(!is.null(profile$availability$exercisesPerSession)){r<-.range(profile$availability$exercisesPerSession);for(s in p$sessions%||%list()){z<-length(s$exercises%||%list());counts[[s$planSessionId]]<-list(exerciseCount=z,minimum=r$min,target=r$target,maximum=r$max,state=.range_state(z,r));if((!is.null(r$min)&&z<r$min)||(!is.null(r$max)&&z>r$max))hard[[length(hard)+1L]]<-list(type="exercise_count",sessionId=s$planSessionId,exerciseCount=z,minimum=r$min,maximum=r$max)}};gaps<-c(Filter(function(x)identical(x$state,"below_minimum"),muscles),Filter(function(x)identical(x$state,"below_minimum"),frequency),Filter(function(x)identical(x$state,"below_minimum"),patterns),Filter(function(x)identical(x$state,"below_minimum"),families));status<-if(length(hard))"hard_constraint_violation"else if(a$coverageCompleteness$mappedFraction<1)"incomplete_coverage"else if(length(gaps))"valid_with_target_gaps"else"valid";md<-db$metadata%||%list();prov<-list(analysisVersion="0.1.0",analysisPolicy="plan-evaluation-v1",planSchemaVersion=p$schemaVersion%||%NULL,profileSchemaVersion=profile$schemaVersion%||%NULL,targetSchemaVersion=target$schemaVersion%||%NULL,relationshipSchemaVersion=relationships$schemaVersion%||%NULL,dbSchemaVersion=md$schemaVersion%||%NULL,dbConverterVersion=md$converterVersion%||%NULL,dbUpstreamSha256=(md$upstream%||%list())$sha256%||%NULL,setCredits=a$analysisMetadata$setCredits);list(summary=list(hardConstraintViolations=length(hard),targetGaps=length(gaps),softPreferenceWarnings=0,satisfiesHardConstraints=!length(hard),meetsTargetMinimums=!length(gaps),evaluationStatus=status),muscleCoverage=muscles,frequency=frequency,movementPatterns=patterns,families=list(coverage=fc,targets=families),equipment=equipment,availability=av,exerciseCounts=counts,preferences=list(findings=list()),constraints=list(violations=hard),coverageCompleteness=a$coverageCompleteness,warnings=if(a$coverageCompleteness$mappedFraction<1)"coverage is incomplete for one or more PLAN exercises"else character(),provenance=prov)
}


generate_plan_from_intent<-function(intent,db,profile=NULL,target=NULL,relationships=NULL,history=NULL,as_of=NULL,...){r<-resolve_intent(intent,db,profile,target,relationships,history,as_of);if(!r$status%in%c("resolved","resolved_with_defaults"))return(list(resolution=r,generation=NULL));list(resolution=r,generation=generate_plan(r$resolvedProfile,r$resolvedTarget,db,policy=r$planningPolicy,training_state=r$generationOptions$trainingState,relationships=relationships,...))}

generate_plan<-function(profile,target,db,policy="full-body-general-v1",training_state=NULL,relationships=NULL,current_plan=NULL,requiredExerciseIds=character(),lockedExerciseIds=character(),requiredFamilyIds=character(),additionalExclusions=character(),options=list()){
  p<-.doc(profile);t<-.doc(target);av<-p$availability%||%list();cycle<-as.integer(av$cycleLengthDays%||%t$periodDays%||%7);n<-as.integer(.scalar(av$sessionsPerCycle));if(!n)n<-1L;k<-as.integer(.scalar(av$exercisesPerSession));if(!k)k<-1L;excluded<-unique(c(.strings(p$constraints$excludedExerciseIds),.strings(additionalExclusions)));required<-unique(c(.strings(requiredExerciseIds),.strings(lockedExerciseIds)))
  eligible<-vapply(names(db$exercises),function(id){e<-.exercise(db,id);eq<-e$source$equipment%||%"other";isTRUE(.annotation(e)$volumeEligible)&&!id%in%excluded&&(eq%in%.strings(p$equipment)||(eq%in%c("body only","bodyweight","none","no equipment")&&length(intersect(.strings(p$equipment),c("body only","bodyweight","none","no equipment")))))},logical(1));ids<-sort(unique(c(required,names(db$exercises)[eligible])))
  if(!length(ids))return(list(status="unsatisfiable",plan=NULL,evaluation=NULL,policy=list(policyId=policy),selectionRationale=list(),unsatisfiedConstraints=list(list(code="NO_ELIGIBLE_EXERCISE")),unsatisfiedTargets=list(),unsatisfiedSoftPreferences=list(),provenance=list(generatorVersion="1.0.0")));ids<-ids[seq_len(min(k,length(ids)))]
  offs<-unique(c(as.integer(av$preferredDayOffsets%||%integer()),seq_len(cycle)-1L));offs<-offs[!offs%in%(av$excludedDayOffsets%||%integer())];if(length(offs)<n)return(list(status="unsatisfiable",plan=NULL,evaluation=NULL,policy=list(policyId=policy),selectionRationale=list(),unsatisfiedConstraints=list(list(code="SESSION_COUNT_CONFLICT")),unsatisfiedTargets=list(),unsatisfiedSoftPreferences=list(),provenance=list(generatorVersion="1.0.0")));offs<-offs[seq_len(n)]
  pid<-options$planId%||%"generated-plan";rid<-options$revisionId%||%"r1";sessions<-lapply(seq_len(n),function(si){exs<-lapply(seq_along(ids),function(ei)list(prescriptionId=sprintf("rx-%02d-%02d",si,ei),exerciseId=ids[[ei]],order=ei,sets=1L,reps=list(min=6L,target=8L,max=12L),effort=list(rir=2L)));list(planSessionId=paste0("session-",si),dayOffset=offs[[si]],exercises=exs)});plan<-list(schemaVersion="0.2.0",planId=pid,revisionId=rid,name=options$name%||%"Generated plan",cycle=list(lengthDays=cycle),sessions=sessions);ev<-evaluate_plan(plan,db,p,t,relationships);good<-isTRUE(ev$summary$satisfiesHardConstraints);list(status=if(good){if(ev$summary$meetsTargetMinimums)"generated"else"generated_with_target_gaps"}else"unsatisfiable",plan=if(good)plan else NULL,evaluation=ev,policy=list(policyId=policy,policyVersion="1.0.0"),selectionRationale=lapply(ids,function(id)list(exerciseId=id,reasonCodes="DETERMINISTIC_RANKING")),unsatisfiedConstraints=ev$constraints$violations,unsatisfiedTargets=list(),unsatisfiedSoftPreferences=list(),provenance=list(generatorVersion="1.0.0",policyId=policy,setCredits=.set_credits(db)))
}

.active_plan<-function(h,asof){hits<-list();for(p in h$plans%||%list())for(a in h$planActivations%||%list())if(identical(a$planId,p$planId)&&identical(a$revisionId,p$revisionId)){from<-.parse_time(a$effectiveFrom);to<-.parse_time(a$effectiveTo);if(!is.na(from)&&from<=asof&&(is.null(a$effectiveTo)||is.na(to)||asof<to))hits[[length(hits)+1L]]<-list(plan=p,activation=a,from=from)};if(length(hits)>1)hits<-hits[order(vapply(hits,function(x)as.numeric(x$from),numeric(1)),decreasing=TRUE)];if(length(hits))hits[[1L]]else NULL}
.scheduled_dates<-function(plan,activation,start,end,timezone="UTC"){if(is.null(activation$effectiveFrom))return(list());anchor<-as.Date(.parse_time(activation$effectiveFrom,timezone),tz=timezone);cycle<-as.integer(plan$cycle$lengthDays%||%7);out<-list();cursor<-anchor;while(cursor<=end){for(s in plan$sessions%||%list()){d<-cursor+as.integer(s$dayOffset%||%0);if(d>=start&&d<=end)out[[length(out)+1L]]<-list(date=d,session=s)};cursor<-cursor+cycle};out}

derive_training_state <- function(history, db, as_of, window="last_28_days", relationships=NULL, target=NULL, timezone="UTC") {
  h <- .doc(history); asof <- .parse_time(as_of, timezone)
  if (is.na(asof)) stop("as_of must be an offset-aware timestamp")
  active <- .active_plan(h, asof); end <- as.Date(asof, tz=timezone)
  if (identical(window, "last_7_days")) width <- 7L else if (identical(window, "last_28_days")) width <- 28L else width <- 1L
  start <- if (is.list(window)) as.Date(window$start) else end-width+1L
  if (is.list(window)) end <- min(end, as.Date(window$end)); if (start > end) stop("history window start must not be after end")
  selected <- Filter(function(w) { z <- .parse_time(w$startTime, timezone); !is.na(z) && z <= asof && as.Date(z,tz=timezone) >= start && as.Date(z,tz=timezone) <= end }, h$workouts %||% list())
  exids <- character()
  if (!is.null(active)) for (s in active$plan$sessions %||% list()) exids <- c(exids, vapply(s$exercises %||% list(), function(x) x$exerciseId %||% "", character(1)))
  for (w in selected) exids <- c(exids, vapply(w$exercises %||% list(), function(x) x$exerciseId %||% "", character(1)))
  exids <- sort(unique(exids[nzchar(exids)])); states <- list()
  for (id in exids) {
    obs <- list(); for (w in selected) for (e in w$exercises %||% list()) if (identical(e$exerciseId,id)) obs[[length(obs)+1L]] <- list(w=w,e=e)
    if (length(obs)) obs <- obs[order(vapply(obs,function(x)as.numeric(.parse_time(x$w$startTime)),numeric(1)))]
    last <- if(length(obs)) obs[[length(obs)]] else NULL; csets <- function(e) Filter(.counted_set,e$sets %||% list())
    states[[id]] <- list(exerciseId=id,lastPerformedAt=if(is.null(last))NULL else last$w$startTime,lastActual=if(is.null(last))NULL else list(exerciseId=id,sets=csets(last$e)),latestPerformance=if(is.null(last))NULL else list(sessionId=last$w$sessionId,timestamp=last$w$startTime,exerciseId=id,exercisePrescriptionId=last$e$exercisePrescriptionId,sets=csets(last$e)),recentPerformances=lapply(obs,function(x)list(sessionId=x$w$sessionId,timestamp=x$w$startTime,exerciseId=id,exercisePrescriptionId=x$e$exercisePrescriptionId,sets=csets(x$e))),recentSessionCount=length(obs),recentCompletedSetCount=sum(vapply(obs,function(x)sum(vapply(x$e$sets%||%list(),.counted_set,logical(1))),numeric(1))),recentReps=if(is.null(last))NULL else as.list(vapply(Filter(function(x)!is.null(x$reps),last$e$sets%||%list()),function(x)as.numeric(x$reps),numeric(1))),recentLoads=if(is.null(last))NULL else lapply(Filter(function(x)!is.null(x$load),last$e$sets%||%list()),function(x)x$load),recentRPE=if(is.null(last))NULL else as.list(vapply(Filter(function(x)!is.null(x$rpe),last$e$sets%||%list()),function(x)as.numeric(x$rpe),numeric(1))),recentRIR=if(is.null(last))NULL else as.list(vapply(Filter(function(x)!is.null(x$rir),last$e$sets%||%list()),function(x)as.numeric(x$rir),numeric(1))),substitutionCount=sum(vapply(obs,function(x)!is.null(x$e$substitution),logical(1))),unplannedCount=sum(vapply(obs,function(x)is.null(x$e$exercisePrescriptionId),logical(1))))
  }
  ap <- list(); adherence <- list()
  if (!is.null(active)) {
    p <- active$plan; anchor <- as.Date(.parse_time(active$activation$effectiveFrom,timezone),tz="UTC"); cycle <- as.integer(p$cycle$lengthDays %||% 7L)
    ap <- list(planId=p$planId,revisionId=p$revisionId,phaseId=NULL,cyclePosition=as.integer(as.numeric(end-anchor,units="days") %% cycle)+1L)
    nx <- Filter(function(x)x$date>=end,.scheduled_dates(p,active$activation,end,end+cycle,timezone)); ap$nextScheduledOccurrence <- if(length(nx)) list(scheduledDate=as.character(nx[[1L]]$date),planSessionId=nx[[1L]]$session$planSessionId) else NULL
    for (o in .scheduled_dates(p,active$activation,start,end,timezone)) {
      w <- Filter(function(x){r<-x$planReference%||%list();identical(r$planId,p$planId)&&identical(r$revisionId,p$revisionId)&&identical(r$planSessionId,o$session$planSessionId)&&as.Date(.parse_time(x$startTime,timezone),tz=timezone)==o$date},selected)
      adherence[[length(adherence)+1L]] <- list(subject_id=h$subjectId,period_start=as.character(start),period_end=as.character(end),period_type="custom_date_range",scheduled_date=as.character(o$date),plan_id=p$planId,revision_id=p$revisionId,plan_session_id=o$session$planSessionId,session_id=if(length(w))w[[1L]]$sessionId else NULL,timestamp=if(length(w))w[[1L]]$startTime else NULL,session_status=if(length(w))"completed" else "missed_planned_session",planned_exercises=length(o$session$exercises%||%list()),planned_sets=sum(vapply(o$session$exercises%||%list(),function(x).scalar(x$sets%||%0),numeric(1))),missing_prescriptions=if(length(w))0L else length(o$session$exercises%||%list()),actual_counted_sets=if(length(w))sum(vapply(w[[1L]]$exercises%||%list(),function(x)sum(vapply(x$sets%||%list(),.counted_set,logical(1))),numeric(1)))else 0L,session_adherence=if(length(w))1 else 0)
    }
  }
  md <- db$metadata%||%list(); prov <- list(stateVersion="0.1.0",asOf=as.character(as_of),historyWindow=list(type=if(is.character(window))window else "custom_date_range",start=as.character(start),end=as.character(end),timezone="UTC"),dbSchemaVersion=md$schemaVersion%||%NULL,dbConverterVersion=md$converterVersion%||%NULL,setCredits=.set_credits(db))
  list(stateVersion="0.1.0",subjectId=h$subjectId%||%NULL,asOf=as.character(as_of),historyWindow=prov$historyWindow,activePlan=ap,exerciseState=states,familyState=list(),muscleState=list(),adherenceState=list(sessionAdherence=adherence,missedScheduledOccurrences=Filter(function(x)x$session_status=="missed_planned_session",adherence)),sessionState=adherence,provenance=prov)
}

apply_progression_policy <- function(policy, prescription, exercise_state, db=NULL, parameters=list()) {
  pid <- if (is.character(policy)) policy else policy$policyId; p <- .doc(prescription); st <- exercise_state %||% list(); before <- p[intersect(names(p),c("load","reps","sets"))]
  result <- function(type,reasons,after=before,evidence=list()) list(schemaVersion="0.1.0",decisionType=type,policyId=pid,policyVersion="1.0.0",planId=st$planContext$planId%||%st$planId%||%NULL,revisionId=st$planContext$revisionId%||%st$revisionId%||%NULL,prescriptionId=p$prescriptionId,exerciseId=p$exerciseId,before=before,after=after,reasonCodes=sort(unique(reasons)),evidence=evidence,provenance=st$provenance%||%list())
  if (pid=="hold-v1") return(result("hold","POLICY_HOLD")); if(isTRUE(st$noActive))return(result("insufficient_data","NO_ACTIVE_PLAN")); actual<-st$lastActual;if(is.null(actual))return(result("insufficient_data",c("NO_RECENT_PERFORMANCE","NO_MATCHED_ACTUAL")));required<-as.integer(.scalar(p$sets%||%0));sets<-Filter(.counted_set,actual$sets%||%list());if(length(sets)<required)return(result("hold",c("SET_TARGET_NOT_COMPLETED","INCOMPLETE_WORKOUT"),evidence=list(plannedSetCount=required,actualSetCount=length(sets))));top<-.range(p$reps)$max;if(any(vapply(sets[seq_len(required)],function(x)is.null(x$reps)||x$reps<top,logical(1))))return(result("hold","REP_TARGET_NOT_ACHIEVED",evidence=list(sets=sets)))
  effort<-p$effort%||%list();for(metric in c("rpe","rir"))if(!is.null(effort[[metric]])){vals<-vapply(sets,function(x)as.numeric(x[[metric]]%||%NA),numeric(1));if(any(is.na(vals)))return(result("insufficient_data","INSUFFICIENT_EFFORT_DATA"));r<-.range(effort[[metric]]);lo<-r$min%||%r$target;hi<-r$max%||%r$target;bad<-if(metric=="rpe")c(if(any(vals<lo))"EFFORT_TOO_LOW",if(any(vals>hi))"EFFORT_TOO_HIGH")else c(if(any(vals<lo))"EFFORT_TOO_HIGH",if(any(vals>hi))"EFFORT_TOO_LOW");if(length(bad))return(result("hold",bad,evidence=list(actualEffort=as.list(vals))))}
  inc<-parameters$loadIncrement;load<-p$load;if(is.null(load)||is.null(inc))return(result("insufficient_data","INSUFFICIENT_LOAD_DATA"));if(!load$unit%in%c("kg","lb","g")||!identical(load$unit,inc$unit))return(result("insufficient_data","INCOMPATIBLE_LOAD_UNIT"));after<-before;after$load<-list(unit=load$unit,value=round(as.numeric(load$value)+as.numeric(inc$value),6));result("increase_load",c("REP_TARGET_ACHIEVED","EFFORT_WITHIN_TARGET"),after=after,evidence=list(previousLoad=load,newLoad=after$load))
}
suggest_progression <- function(plan,training_state,policy="double-progression-v1",parameters=list()){p<-.doc(plan);s<-.doc(training_state);active<-s$activePlan%||%list();if(!is.null(active$revisionId)&&!identical(active$revisionId,p$revisionId))stop("plan is not the active TrainingState revision");out<-list();for(se in p$sessions%||%list())for(rx in se$exercises%||%list()){es<-s$exerciseState[[rx$exerciseId]]%||%list();es$planContext<-list(planId=p$planId,revisionId=p$revisionId,provenance=s$provenance%||%list());es$noActive<-is.null(active$revisionId);out[[length(out)+1L]]<-apply_progression_policy(policy,rx,es,parameters=parameters)};out}

adapt_plan <- function(profile,target,current_plan,history,db,policy="general-adaptive-v1",relationships=NULL,training_state=NULL,as_of=NULL,options=list()){
  current<-.doc(current_plan);if(is.null(training_state)){as_of<-as_of%||%options$asOf%||%history$asOf;if(is.null(as_of))stop("adapt_plan requires as_of or options$asOf");training_state<-derive_training_state(history,db,as_of=as_of,window=options$window%||%"last_28_days",relationships=relationships,target=target)};ev<-evaluate_plan(current,db,profile,target,relationships);params<-options$parameters%||%list(loadIncrement=list(value=2.5,unit="kg"));decisions<-suggest_progression(current,training_state,parameters=params);changed<-any(vapply(decisions,function(x)identical(x$decisionType,"increase_load"),logical(1)));proposed<-NULL;if(changed){proposed<-current;proposed$revisionId<-options$revisionId%||%if(grepl("^r[0-9]+$",current$revisionId))paste0("r",as.integer(sub("^r","",current$revisionId))+1L)else paste0(current$revisionId,"-adaptive-1");for(d in decisions)if(d$decisionType=="increase_load")for(s in proposed$sessions)for(rx in s$exercises)if(identical(rx$prescriptionId,d$prescriptionId))rx$load<-d$after$load};pe<-if(!is.null(proposed))evaluate_plan(proposed,db,profile,target,relationships)else NULL;list(status=if(is.null(proposed))"no_change"else"revision_proposed",currentPlan=current,proposedPlan=proposed,currentEvaluation=ev,proposedEvaluation=pe,trainingState=training_state,decisions=decisions,changes=list(),unresolvedIssues=list(),policy=list(policyId=policy,policyVersion="1.0.0"),provenance=list(coachingVersion="1.0.0",asOf=training_state$asOf,setCredits=.set_credits(db)))
}

