.state_observations<-function(state,key){s<-.doc(state);rows<-lapply(s[[key]]%||%list(),function(x){z<-as.data.frame(x,stringsAsFactors=FALSE);z});if(length(rows))do.call(rbind,rows)else data.frame()}
