coach_decision_observations<-function(decisions){d<-.doc(decisions);if(is.list(d)&&!is.null(d$decisions))d<-d$decisions;if(!length(d))return(data.frame());do.call(rbind,lapply(d,function(x)data.frame(decision_id=x$decisionId%||%NA_character_,decision_type=x$decisionType%||%NA_character_,policy_id=x$policyId%||%NA_character_,prescription_id=x$prescriptionId%||%NA_character_,exercise_id=x$exerciseId%||%NA_character_,reason_codes=paste(.strings(x$reasonCodes),collapse="|"),stringsAsFactors=FALSE)))}
plan_evaluation_observations<-function(evaluation){e<-.doc(evaluation);rows<-lapply(names(e$muscleCoverage%||%list()),function(k){x<-e$muscleCoverage[[k]];data.frame(muscle_id=k,actual_effective_sets=x$actualEffectiveSets%||%NA_real_,target=x$target%||%NA_real_,state=x$state%||%NA_character_,stringsAsFactors=FALSE)});if(length(rows))do.call(rbind,rows)else data.frame()}
longitudinal_volume<-function(workouts,database){ws<-if(is.list(workouts)&&!is.null(workouts$schemaVersion))list(workouts)else workouts;rows<-lapply(ws,function(w){x<-effective_sets(w,database);if(!nrow(x))return(NULL);a<-aggregate(x$effective_sets,list(x$muscle),sum);data.frame(session_id=w$sessionId,start_time=w$startTime,muscle=a$Group.1,effective_sets=a$x,stringsAsFactors=FALSE)});rows<-Filter(Negate(is.null),rows);if(length(rows))do.call(rbind,rows)else .empty_df(session_id=character(),start_time=character(),muscle=character(),effective_sets=numeric())}
analysis_provenance<-function(db=NULL,state=NULL,as_of=NULL,window=NULL)list(packageVersion="1.14.0",dbSchemaVersion=db$metadata$schemaVersion%||%NULL,dbConverterVersion=db$metadata$converterVersion%||%NULL,setCredits=if(!is.null(db)) .set_credits(db)else NULL,asOf=as_of%||%state$asOf%||%NULL,historyWindow=window%||%state$historyWindow%||%NULL)

# The helpers below are the R translation of the released deterministic
# planning/state policies.  They intentionally live in the same source file
# as the document functions so an installed package has no runtime bridge.
.deepcopy <- function(x) unserialize(serialize(x, NULL, version=3))
.planning_policy <- function(id) {
  if (identical(id, "full-body-general-v1")) return(list(policyId=id,policyVersion="1",description="Reference deterministic full-body construction policy.",splitStrategy="full_body_every_session",exerciseSelectionStrategy="eligible_target_coverage_v1",volumeAllocationStrategy="greatest_deficit_one_set_v1",frequencyStrategy="least_exposed_session_v1",tieBreakingStrategy="explicit_tuple_then_exercise_id_v1",parameters=list(defaultSessionsPerCycle=3L,setBlock=1L,reps=list(min=6L,target=8L,max=10L),effort=list(rir=2L),allowUnverifiableEquipment=FALSE,preferHistoryContinuity=TRUE,avoidSameFamilyInSession=TRUE)))
  if (identical(id, "upper-lower-general-v1")) return(list(policyId=id,policyVersion="1",description="Reference deterministic alternating upper/lower construction policy.",splitStrategy="upper_lower_alternating",exerciseSelectionStrategy="eligible_target_coverage_v1",volumeAllocationStrategy="greatest_deficit_one_set_v1",frequencyStrategy="least_exposed_compatible_session_v1",tieBreakingStrategy="explicit_tuple_then_exercise_id_v1",parameters=list(defaultSessionsPerCycle=4L,minimumSessionsPerCycle=2L,setBlock=1L,reps=list(min=6L,target=8L,max=10L),effort=list(rir=2L),allowUnverifiableEquipment=FALSE,preferHistoryContinuity=TRUE,avoidSameFamilyInSession=TRUE,upperMuscles=c("chest","lats","middle_back","traps","biceps","triceps","shoulders","forearms","rotator_cuff"),lowerMuscles=c("quadriceps","hamstrings","glutes","calves","abductors","adductors","hip_flexors","lower_back"),upperPatterns=c("horizontal_press","horizontal_press_triceps_bias","incline_press","decline_press","vertical_press","horizontal_pull","vertical_pull","chest_fly","elbow_extension","elbow_flexion","shoulder_abduction","shoulder_flexion","shoulder_external_rotation","shoulder_internal_rotation","face_pull","reverse_fly","shrug","upright_row"),lowerPatterns=c("squat","squat_quad_bias","lunge","step_up","leg_press","hip_hinge","hip_extension","hip_flexion","knee_extension","knee_flexion","plantar_flexion_bent_knee","plantar_flexion_straight_knee","hip_abduction","hip_adduction"))))
  NULL
}
.session_kind <- function(pol,i) if (identical(pol$splitStrategy,"upper_lower_alternating")) if ((i-1L)%%2==0) "upper" else "lower" else "full_body"
.compatible <- function(candidate,i,pol) { kind<-.session_kind(pol,i);if(kind=="full_body")return(TRUE);a<-candidate$annotation%||%list();any(c(.strings(a$direct),.strings(a$indirect),.strings(a$patterns))%in%c(pol$parameters[[paste0(kind,"Muscles")]]%||%character(),pol$parameters[[paste0(kind,"Patterns")]]%||%character())) }
.available_equipment <- function(p) {z<-.strings(p$equipment);if(length(intersect(z,c("bodyweight","no equipment","none"))))z<-unique(c(z,"body only"));z}
.candidate_pool <- function(db,p,rel,required,extra,pol) {
  cst<-p$constraints%||%list(); excluded<-unique(c(.strings(cst$excludedExerciseIds),.strings(extra)));excluded_f<- .strings(cst$excludedFamilyIds);available<-.available_equipment(p);out<-list();block<-list()
  for(id in sort(names(db$exercises))) {e<-.exercise(db,id);a<-.annotation(e);f<-family_for(rel,id);fid<-if(is.null(f))NULL else f$familyId;eq<-e$source$equipment%||%NULL;ok<-isTRUE(a$volumeEligible)&&!id%in%excluded&&(is.null(fid)||!fid%in%excluded_f);if(is.null(eq)||as.character(eq)%in%c("None","other")){ok<-ok&&isTRUE(pol$parameters$allowUnverifiableEquipment)}else if(eq%in%c("body only","bodyweight","no equipment","none")){ok<-ok&&length(intersect(available,c("body only","bodyweight","no equipment","none")))>0}else ok<-ok&&isTRUE(eq%in%available);if(isTRUE(ok))out[[length(out)+1L]]<-list(exerciseId=id,name=e$name%||%e$source$name%||%id,annotation=a,familyId=fid,equipment=eq)}
  ids<-vapply(out,function(x)x$exerciseId,character(1));for(id in sort(required)){e<-.exercise(db,id);if(id%in%excluded)block[[length(block)+1L]]<-list(code="EXCLUDED_REQUIRED_EXERCISE",exerciseId=id)else if(is.null(e))block[[length(block)+1L]]<-list(code="NO_ELIGIBLE_EXERCISE",exerciseId=id,detail="unknown exerciseId")else if(!id%in%ids){eq<-e$source$equipment%||%NULL;code<-if(!is.null(eq)&&!eq%in%available)"NO_AVAILABLE_EQUIPMENT"else"NO_ELIGIBLE_EXERCISE";block[[length(block)+1L]]<-list(code=code,exerciseId=id)}};list(candidates=out,blockers=block)
}
.session_count <- function(p,pol) {r<-.range((p$availability%||%list())$sessionsPerCycle);lo<-r$min%||%1;hi<-r$max;desired<-r$target%||%pol$parameters$defaultSessionsPerCycle;if(identical(hi,0)||(!is.null(hi)&&hi==0))return(list(values=integer(),errors=list(list(code="SESSION_COUNT_CONFLICT",detail="canonical PLAN requires at least one session"))));lo<-max(1,lo,pol$parameters$minimumSessionsPerCycle%||%1);if(!is.null(hi)&&lo>hi)return(list(values=integer(),errors=list(list(code="SESSION_COUNT_CONFLICT",minimum=lo,maximum=hi))));if(!is.null(hi))desired<-min(desired,hi);desired<-max(desired,lo);v<-seq.int(lo,if(is.null(hi))desired else hi);list(values=v[order(abs(v-desired),ifelse(v<=desired,0,1),v)],errors=list())}
.day_offsets <- function(cycle,count,preferred,excluded,locked=integer()) {allowed<-setdiff(seq.int(0,cycle-1L),excluded);locked<-sort(unique(locked));if(length(allowed)<count||length(locked)>count||any(!locked%in%allowed))return(NULL);chosen<-unique(c(locked,sort(intersect(preferred,allowed))));chosen<-head(chosen,count);while(length(chosen)<count){choices<-setdiff(allowed,chosen);spacing<-function(d)if(!length(chosen))cycle else min(pmin((d-chosen)%%cycle,(chosen-d)%%cycle));chosen<-c(chosen,choices[order(-vapply(choices,spacing,numeric(1)),choices)[1L]])};sort(chosen)}
.add_prescription <- function(plan,si,candidate,pol,rationale,reason="TARGET_COVERAGE") {s<-plan$sessions[[si]];j<-which(vapply(s$exercises%||%list(),function(x)identical(x$exerciseId,candidate$exerciseId),logical(1)));if(length(j)){s$exercises[[j[1L]]]$sets<-.scalar(s$exercises[[j[1L]]]$sets)+pol$parameters$setBlock}else{s$exercises[[length(s$exercises)+1L]]<-list(prescriptionId=sprintf("rx-%02d-%02d",si,length(s$exercises)+1L),exerciseId=candidate$exerciseId,exerciseName=candidate$name,order=length(s$exercises)+1L,sets=pol$parameters$setBlock,reps=.deepcopy(pol$parameters$reps),effort=.deepcopy(pol$parameters$effort),setType="working")};plan$sessions[[si]]<-s;rationale[[candidate$exerciseId]]<-sort(unique(c(rationale[[candidate$exerciseId]]%||%character(),reason)));list(plan=plan,rationale=rationale)}
.above_max <- function(e) any(vapply(c(e$muscleCoverage%||%list(),e$frequency%||%list(),e$movementPatterns%||%list(),e$families$targets%||%list()),function(x)identical(x$state,"above_maximum"),logical(1)))
.deficits <- function(e,phase="minimum") {parts<-list(list(kind="muscle",x=e$muscleCoverage,key="actualEffectiveSets"),list(kind="frequency",x=e$frequency,key="normalizedExposuresPer7Days"),list(kind="pattern",x=e$movementPatterns,key="plannedSets"),list(kind="family",x=e$families$targets,key="plannedSets"));r<-list();for(pt in parts)for(k in names(pt$x%||%list())){z<-pt$x[[k]];req<-if(phase=="minimum")z$minimum else z$target;act<-z[[pt$key]]%||%0;if(!is.null(req)&&act<req)r[[length(r)+1L]]<-c(list(deficit=as.numeric(req-act),kind=pt$kind,key=k),list(row=z))};if(!length(r))return(list());r[order(-vapply(r,function(x)x$deficit,numeric(1)),vapply(r,function(x)x$kind,character(1)),vapply(r,function(x)x$key,character(1)))]}
.contributes <- function(cand,kind,key,cr) {a<-cand$annotation%||%list();if(kind=="muscle")return((if(key%in%.strings(a$direct))cr[["direct"]]else 0)+(if(key%in%.strings(a$indirect))cr[["indirect"]]else 0)+(if(key%in%.strings(a$stabilizers))cr[["stabilizer"]]else 0));if(kind=="pattern")return(as.numeric(key%in%.strings(a$patterns)));if(kind=="family")return(as.numeric(identical(cand$familyId,key)));as.numeric(key%in%c(.strings(a$direct),.strings(a$indirect)))}
.session_exposes <- function(session,key,db) any(vapply(session$exercises%||%list(),function(rx){a<-.annotation(.exercise(db,rx$exerciseId));key%in%c(.strings(a$direct),.strings(a$indirect))},logical(1)))
.candidate_order <- function(xs,rank) {if(!length(xs))return(integer());scores<-lapply(xs,rank);m<-do.call(rbind,lapply(scores,function(x){z<-as.numeric(x[seq_len(length(x)-1L)]);length(z)<-8L;z}));id<-vapply(xs,function(x)x$exerciseId,character(1));do.call(order,c(as.data.frame(m),list(id),list(method="radix")))}

# Full deterministic target-deficit generator, including locked/current-plan
# placement and evaluator gating.
generate_plan <- function(profile,target,db,policy="full-body-general-v1",training_state=NULL,relationships=NULL,current_plan=NULL,requiredExerciseIds=character(),lockedExerciseIds=character(),requiredFamilyIds=character(),additionalExclusions=character(),options=list()) {
  p<-.doc(profile);t<-.doc(target);pol<-if(is.character(policy)) .planning_policy(policy) else .doc(policy);bad<-function(status,plan=NULL,ev=NULL,issues=list())list(status=status,plan=plan,evaluation=ev,policy=pol%||%list(policyId=policy),selectionRationale=list(),unsatisfiedConstraints=issues,unsatisfiedTargets=list(),unsatisfiedSoftPreferences=list(),provenance=list(generatorVersion="0.1.0",policyId=pol$policyId%||%policy,setCredits=.set_credits(db)));if(is.null(pol))return(bad("invalid_input",issues=list(list(code="INVALID_PLANNING_POLICY"))));if(!is.list(p)||!is.list(t))return(bad("invalid_input",issues=list(list(code="INVALID_INPUT"))));errs<-c(validate_training_profile(p,db,relationships),validate_target(t));if(length(t$families%||%list())&&!is.null(t$families)&&is.null(relationships))errs<-c(errs,"family targets require exercise relationships");if(length(errs))return(bad("invalid_input",issues=lapply(sort(unique(errs)),function(x)list(code="INVALID_INPUT",detail=x))));av<-p$availability%||%list();cycle<-as.integer(av$cycleLengthDays%||%t$periodDays%||%7);limits<-.range(av$exercisesPerSession);counts<-.session_count(p,pol);if(length(counts$errors))return(bad("unsatisfiable",issues=counts$errors));locked<-unique(.strings(lockedExerciseIds));required<-unique(c(.strings(requiredExerciseIds),locked));pool<-.candidate_pool(db,p,relationships,required,additionalExclusions,pol);if(length(pool$blockers))return(bad("unsatisfiable",issues=pool$blockers));cands<-pool$candidates;current<-.doc(current_plan);loc<-list();if(length(locked)){if(is.null(current))return(bad("unsatisfiable",issues=lapply(locked,function(x)list(code="LOCKED_EXERCISE_CONFLICT",exerciseId=x,detail="locked exercises require current_plan"))));for(id in locked)loc[[id]]<-sort(unique(vapply(Filter(function(s)any(vapply(s$exercises%||%list(),function(x)identical(x$exerciseId,id),logical(1))),current$sessions%||%list()),function(s)as.integer(s$dayOffset),integer(1))));if(any(!lengths(loc)))return(bad("unsatisfiable",issues=lapply(locked,function(x)list(code="LOCKED_EXERCISE_CONFLICT",exerciseId=x,detail="exercise does not occur in current_plan"))))};locked_offsets<-sort(unique(unlist(loc,use.names=FALSE)));if(any(locked_offsets%in%as.integer(av$excludedDayOffsets%||%integer())||locked_offsets<0|locked_offsets>=cycle))return(bad("unsatisfiable",issues=list(list(code="LOCKED_EXERCISE_CONFLICT",detail="locked current-plan dayOffset is unavailable in generated cycle"))));offsets<-lapply(counts$values,function(n).day_offsets(cycle,n,as.integer(av$preferredDayOffsets%||%integer()),as.integer(av$excludedDayOffsets%||%integer()),locked_offsets));ok<-which(!vapply(offsets,is.null,logical(1)));if(!length(ok))return(bad("unsatisfiable",issues=list(list(code="SESSION_COUNT_CONFLICT",detail="not enough permitted day offsets"))));n<-counts$values[ok[1L]];offs<-offsets[[ok[1L]]];plan<-list(schemaVersion="0.2.0",planId=options$planId%||%"generated-plan",revisionId=options$revisionId%||%"r1",name=options$name%||%paste("Generated",pol$policyId),description=NULL,cycle=list(lengthDays=cycle),sessions=lapply(seq_along(offs),function(i)list(planSessionId=paste0("session-",i),dayOffset=offs[i],name=if(.session_kind(pol,i)=="full_body")paste("Session",i) else paste(tools::toTitleCase(gsub("_"," ",.session_kind(pol,i))),floor((i-1L)/2)+1L),exercises=list())));rationale<-list();existing<-if(is.null(current))character()else unique(unlist(lapply(current$sessions%||%list(),function(s)vapply(s$exercises%||%list(),function(x)x$exerciseId%||%"",character(1)))));prefs<-p$exercisePreferences%||%list();history<-(.doc(training_state)%||%list())$exerciseState%||%list();continuity<-options$continuity%||%"preserve";if(!continuity%in%c("preserve","neutral","vary"))return(bad("invalid_input",issues=list(list(code="INVALID_INPUT",detail="options.continuity must be preserve, neutral, or vary"))));in_set<-function(x,s)as.numeric(!is.null(x)&&length(x)&&x%in%.strings(s));rank<-function(cand,kind,key){id<-cand$exerciseId;fam<-cand$familyId;h<-history[[id]]%||%list();good<-id%in%names(history)&&((h$prescriptionAdherence$setAdherence%||%1)>=.5);continuity_rank<-if(continuity=="preserve")c(-in_set(id,existing),-as.numeric(good))else if(continuity=="neutral")c(0,0)else c(in_set(id,existing),as.numeric(good));c(-in_set(id,required),continuity_rank,-in_set(id,prefs$preferredExerciseIds),-in_set(fam,prefs$preferredFamilyIds),-.contributes(cand,kind,key,.set_credits(db)),in_set(id,prefs$avoidedExerciseIds)+in_set(fam,prefs$avoidedFamilyIds),id)};
  session_index<-function(off)match(off,vapply(plan$sessions,function(s)s$dayOffset,numeric(1)));for(id in locked){cand<-cands[[match(id,vapply(cands,function(x)x$exerciseId,character(1)))]];for(off in loc[[id]]){si<-session_index(off);if(!.compatible(cand,si,pol))return(bad("unsatisfiable",issues=list(list(code="LOCKED_EXERCISE_CONFLICT",exerciseId=id,dayOffset=off,detail="locked exercise is incompatible with generated split role"))));z<-.add_prescription(plan,si,cand,pol,rationale,"LOCKED_EXERCISE");plan<-z$plan;rationale<-z$rationale}}
  for(fid in sort(unique(.strings(requiredFamilyIds)))){choices<-Filter(function(x)identical(x$familyId,fid),cands);if(!length(choices))return(bad("unsatisfiable",issues=list(list(code="NO_ELIGIBLE_FAMILY_EXERCISE",familyId=fid))));ord<-.candidate_order(choices,function(x)rank(x,"muscle",""));cand<-choices[[ord[1L]]];si<-which(vapply(seq_along(plan$sessions),function(i).compatible(cand,i,pol)&&length(plan$sessions[[i]]$exercises)<(limits$max%||%Inf),logical(1)))[1L];if(is.na(si))return(bad("unsatisfiable",issues=list(list(code="EXERCISE_COUNT_CONFLICT",familyId=fid))));z<-.add_prescription(plan,si,cand,pol,rationale,"REQUIRED_FAMILY");plan<-z$plan;rationale<-z$rationale}
  for(req_i in seq_along(sort(setdiff(required,locked)))){id<-sort(setdiff(required,locked))[[req_i]];cand<-cands[[match(id,vapply(cands,function(x)x$exerciseId,character(1)))]];si<-which(vapply(seq_along(plan$sessions),function(i).compatible(cand,i,pol)&&length(plan$sessions[[i]]$exercises)<(limits$max%||%Inf),logical(1)))[1L];if(is.na(si))return(bad("unsatisfiable",issues=list(list(code="EXERCISE_COUNT_CONFLICT",exerciseId=id))));z<-.add_prescription(plan,si,cand,pol,rationale,"REQUIRED_EXERCISE");plan<-z$plan;rationale<-z$rationale;break}
  ev<-evaluate_plan(plan,db,p,t,relationships);for(phase in c("minimum","target")){guard<-0L;repeat{guard<-guard+1L;d<-.deficits(ev,phase);if(!length(d)||guard>200L)break;one<-d[[1L]];eligible<-Filter(function(x).contributes(x,one$kind,one$key,.set_credits(db))>0,cands);if(!length(eligible))break;eligible<-eligible[.candidate_order(eligible,function(x)rank(x,one$kind,one$key))];accepted<-FALSE;for(cand in eligible){sis<-which(vapply(seq_along(plan$sessions),function(i).compatible(cand,i,pol)&&length(plan$sessions[[i]]$exercises)<(limits$max%||%Inf)&&!(one$kind=="frequency"&&any(vapply(plan$sessions[[i]]$exercises%||%list(),function(x)identical(x$exerciseId,cand$exerciseId),logical(1)))),logical(1)));sis<-sis[if(one$kind=="frequency")order(vapply(sis,function(i)as.integer(.session_exposes(plan$sessions[[i]],one$key,db)),integer(1)),vapply(sis,function(i)length(plan$sessions[[i]]$exercises),integer(1)),sis)else order(vapply(sis,function(i)length(plan$sessions[[i]]$exercises),integer(1)),sis)];for(si in sis){draft<-.deepcopy(plan);z<-.add_prescription(draft,si,cand,pol,rationale);draft<-z$plan;ee<-evaluate_plan(draft,db,p,t,relationships);if(!.above_max(ee)){plan<-draft;rationale<-z$rationale;ev<-ee;accepted<-TRUE;break}};if(accepted)break};if(!accepted)break}}
  for(si in seq_along(plan$sessions)){minc<-limits$min%||%1;while(length(plan$sessions[[si]]$exercises)<minc){choices<-Filter(function(x).compatible(x,si,pol)&&length(plan$sessions[[si]]$exercises)<(limits$max%||%Inf),cands);if(!length(choices))return(bad("unsatisfiable",issues=list(list(code="NO_ELIGIBLE_EXERCISE"))));cand<-choices[[.candidate_order(choices,function(x)rank(x,"muscle",""))[1L]]];draft<-.deepcopy(plan);z<-.add_prescription(draft,si,cand,pol,rationale,"DETERMINISTIC_TIE_BREAK");ee<-evaluate_plan(z$plan,db,p,t,relationships);if(.above_max(ee))return(bad("unsatisfiable",issues=list(list(code="SESSION_COUNT_CONFLICT",detail="cannot populate all required sessions without target maximum overshoot"))));plan<-z$plan;rationale<-z$rationale;ev<-ee}}
  if(!isTRUE(ev$summary$satisfiesHardConstraints))return(bad("unsatisfiable",ev,list(list(code="EVALUATOR_HARD_CONSTRAINT",detail=ev$constraints$violations))));gaps<-.deficits(ev,"minimum");list(status=if(length(gaps))"generated_with_target_gaps"else"generated",plan=plan,evaluation=ev,policy=pol,selectionRationale=lapply(sort(names(rationale)),function(id)list(exerciseId=id,reasonCodes=rationale[[id]])),unsatisfiedConstraints=list(),unsatisfiedTargets=lapply(gaps,function(x)list(kind=x$kind,id=x$key)),unsatisfiedSoftPreferences=list(),provenance=list(generatorVersion="0.1.0",policyId=pol$policyId,setCredits=.set_credits(db)))
}

# Preserve the canonical RPE/RIR and heterogeneous-set behavior at the public
# progression boundary.
apply_progression_policy <- function(policy,prescription,exercise_state,db=NULL,parameters=list()) {
  p<-.doc(prescription);st<-exercise_state%||%list();pid<-if(is.character(policy))policy else policy$policyId;before<-p[intersect(names(p),c("load","reps","sets"))];ctx<-st$planContext%||%st;result<-function(type,reasons,after=before,evidence=list())list(schemaVersion="0.1.0",decisionType=type,policyId=pid,policyVersion="1.0.0",planId=ctx$planId%||%NULL,revisionId=ctx$revisionId%||%NULL,prescriptionId=p$prescriptionId,exerciseId=p$exerciseId,before=before,after=after,reasonCodes=sort(unique(reasons)),evidence=evidence,provenance=ctx$provenance%||%list());if(pid=="hold-v1")return(result("hold","POLICY_HOLD"));actual<-st$lastActual;if(is.null(actual))return(result("insufficient_data",c("NO_RECENT_PERFORMANCE","NO_MATCHED_ACTUAL")));planned<-Filter(function(x)(x$setType%||%"working")%in%.counted_types,p$plannedSets%||%list());required<-if(length(planned))length(planned)else as.integer(.scalar(p$sets%||%0));sets<-Filter(.counted_set,actual$sets%||%list());if(length(sets)<required)return(result("hold",c("SET_TARGET_NOT_COMPLETED","INCOMPLETE_WORKOUT"),evidence=list(plannedSetCount=required,actualSetCount=length(sets))));byid<-setNames(planned,vapply(planned,function(x)x$setPrescriptionId%||%"",character(1)));matched<-length(planned)&&any(nzchar(names(byid)))&&all(vapply(sets,function(x)!is.null(x$setPrescriptionId)&&nzchar(x$setPrescriptionId)&&!is.null(byid[[x$setPrescriptionId]]),logical(1)));expected<-if(matched)lapply(sets,function(x)byid[[x$setPrescriptionId]])else if(length(planned))head(planned,required)else rep(list(p),required);rep_top<-function(x){r<-.range(x);r$max%||%r$target%||%r$min};evidence_sets<-lapply(seq_len(min(required,length(sets))),function(i)list(setId=sets[[i]]$setPrescriptionId%||%sets[[i]]$setNumber%||%NULL,plannedReps=expected[[i]]$reps%||%p$reps%||%NULL,actualReps=sets[[i]]$reps%||%NULL));if(length(evidence_sets)<required||any(vapply(seq_along(evidence_sets),function(i)is.null(evidence_sets[[i]]$actualReps)||as.numeric(evidence_sets[[i]]$actualReps)<rep_top(expected[[i]]$reps%||%p$reps),logical(1))))return(result("hold","REP_TARGET_NOT_ACHIEVED",evidence=list(sets=evidence_sets)));eff<-p$effort%||%list();for(metric in c("rpe","rir"))if(!is.null(eff[[metric]])){vals<-vapply(sets[seq_len(required)],function(x)as.numeric(x[[metric]]%||%NA_real_),numeric(1));if(any(is.na(vals)))return(result("insufficient_data","INSUFFICIENT_EFFORT_DATA",evidence=list(sets=evidence_sets,effortType=metric)));er<-.range(eff[[metric]]);lo<-er$min%||%er$target;hi<-er$max%||%er$target;if(metric=="rpe")bad<-c(if(any(vals<lo))"EFFORT_TOO_LOW",if(any(vals>hi))"EFFORT_TOO_HIGH")else bad<-c(if(any(vals<lo))"EFFORT_TOO_HIGH",if(any(vals>hi))"EFFORT_TOO_LOW");if(length(bad))return(result("hold",bad,evidence=list(sets=evidence_sets,actualEffort=as.list(vals))))};load<-p$load;inc<-parameters$loadIncrement;if(is.null(load)||is.null(inc)||is.null(load$value)&&is.null(load$target))return(result("insufficient_data","INSUFFICIENT_LOAD_DATA",evidence=list(sets=evidence_sets)));convert<-function(v,u){u<-tolower(u);if(u=="kg")v else if(u=="g")v/1000 else if(u%in%c("lb","lbs"))v*0.45359237 else stop("unit")};tryCatch({unit<-tolower(load$unit);incunit<-tolower(inc$unit);base<-convert(as.numeric(load$value%||%load$target),unit);delta<-convert(as.numeric(inc$value),incunit);if(!unit%in%c("kg","lb","lbs","g")||!incunit%in%c("kg","lb","lbs","g"))stop("unit");new<-if(unit%in%c("lb","lbs"))(base+delta)/0.45359237 else if(unit=="g")(base+delta)*1000 else base+delta;after<-before;after$load<-list(unit=load$unit,value=round(new,6));result("increase_load",c("REP_TARGET_ACHIEVED","EFFORT_WITHIN_TARGET"),after=after,evidence=list(sets=evidence_sets,previousLoad=load,newLoad=after$load))},error=function(e)result("insufficient_data","INCOMPATIBLE_LOAD_UNIT",evidence=list(sets=evidence_sets)))
}

# The basic derivation is retained for compatibility, then enriched with the
# canonical research tables used by coaching and cohort analysis.
.derive_training_state_basic <- derive_training_state
derive_training_state <- function(history,db,as_of,window="last_28_days",relationships=NULL,target=NULL,timezone="UTC") {
  s<-.derive_training_state_basic(history,db,as_of,window,relationships,target,timezone);h<-.doc(history);start<-as.Date(s$historyWindow$start);end<-as.Date(s$historyWindow$end);active<-s$activePlan%||%list();plan<-NULL;if(!is.null(active$planId))for(p in h$plans%||%list())if(identical(p$planId,active$planId)&&identical(p$revisionId,active$revisionId))plan<-p
  rows<-list();skipped<-list();subs<-list();unplanned<-list();for(w in h$workouts%||%list()){tm<-.parse_time(w$startTime,timezone);if(is.na(tm)||tm> .parse_time(as_of,timezone)||as.Date(tm,tz="UTC")<start||as.Date(tm,tz="UTC")>end)next;for(e in w$exercises%||%list()){rxid<-e$exercisePrescriptionId%||%NULL;sub<-e$substitution%||%list();if(!is.null(sub$plannedPrescriptionId))rxid<-sub$plannedPrescriptionId;if(!is.null(sub$plannedPrescriptionId))subs[[length(subs)+1L]]<-list(prescriptionId=rxid,replacementExerciseId=e$exerciseId,sessionId=w$sessionId,timestamp=w$startTime);if(is.null(rxid))unplanned[[length(unplanned)+1L]]<-list(sessionId=w$sessionId,exerciseId=e$exerciseId,actualSets=length(Filter(.counted_set,e$sets%||%list())));rows[[length(rows)+1L]]<-list(workout=w,exercise=e,prescriptionId=rxid)}}
  prescribed<-if(is.null(plan))list()else unlist(lapply(plan$sessions%||%list(),function(x)x$exercises%||%list()),recursive=FALSE);for(rx in prescribed){occ<-0L;matched<-Filter(function(x)identical(x$prescriptionId,rx$prescriptionId),rows);if(length(matched)) {actual<-sum(vapply(matched,function(x)length(Filter(.counted_set,x$exercise$sets%||%list())),numeric(1)));status<-"matched";sid<-rx$exerciseId;st<-s$exerciseState[[sid]]%||%list(exerciseId=sid);lastm<-matched[[length(matched)]];st$lastActual<-list(exerciseId=lastm$exercise$exerciseId,sets=Filter(.counted_set,lastm$exercise$sets%||%list()));st$recentSessionCount<-length(matched);st$recentCompletedSetCount<-actual;st$recentReps<-as.list(vapply(Filter(function(q)!is.null(q$reps),lastm$exercise$sets%||%list()),function(q)as.numeric(q$reps),numeric(1)));st$recentRIR<-as.list(vapply(Filter(function(q)!is.null(q$rir),lastm$exercise$sets%||%list()),function(q)as.numeric(q$rir),numeric(1)));s$exerciseState[[sid]]<-st}else {actual<-0;status<-"missing_prescription";skipped[[rx$prescriptionId]]<-1L};planned<-as.numeric(.scalar(rx$sets%||%0));rows2<-list(planned_exercise_id=rx$exerciseId,actual_exercise_id=if(length(matched))matched[[1L]]$exercise$exerciseId else NULL,prescription_id=rx$prescriptionId,period=as.character(start),match_status=status,planned_sets_target=planned,actual_sets=actual,set_adherence=list(plannedRange=.range(rx$sets%||%0),actual=actual));s$adherenceState$exercisePrescriptionAdherence[[length(s$adherenceState$exercisePrescriptionAdherence)+1L]]<-rows2}
  if(!is.null(plan))for(m in s$adherenceState$missedScheduledOccurrences%||%list())for(rx in plan$sessions[[match(m$plan_session_id,vapply(plan$sessions,function(q)q$planSessionId,character(1)))]]$exercises%||%list())skipped[[rx$prescriptionId]]<-(skipped[[rx$prescriptionId]]%||%0L)+1L
  if(length(subs)){for(x in subs){z<-s$adherenceState$substitutionHistoryByPrescription[[x$prescriptionId]]%||%list();q<-z[[x$replacementExerciseId]]%||%list(count=0L,sessionIds=list(),timestamps=list());q$count<-q$count+1L;q$sessionIds<-c(q$sessionIds,list(x$sessionId));q$timestamps<-c(q$timestamps,list(x$timestamp));z[[x$replacementExerciseId]]<-q;s$adherenceState$substitutionHistoryByPrescription[[x$prescriptionId]]<-z}}
  s$adherenceState$skippedPrescriptionCounts<-skipped;s$adherenceState$substitutionCountsByPrescription<-lapply(s$adherenceState$substitutionHistoryByPrescription,function(x)sum(vapply(x,function(y)y$count%||%0,numeric(1))));s$adherenceState$unplannedExercises<-unplanned;s$adherenceState$unplannedSets<-sum(vapply(unplanned,function(x)x$actualSets%||%0,numeric(1)));s$adherenceState$substitutionAdjustedCompletion<-sum(vapply(s$adherenceState$exercisePrescriptionAdherence,function(x)x$match_status%in%c("matched","substitution"),logical(1)))
  if(!is.null(relationships)){fs<-list();for(id in names(s$exerciseState)){f<-family_for(relationships,id);if(!is.null(f)){z<-fs[[f$familyId]]%||%list(familyId=f$familyId,recentExerciseIds=character(),mostRecentExerciseId=NULL,explicitSubstitutionCount=0L,variantHistory=list());z$recentExerciseIds<-sort(unique(c(z$recentExerciseIds,id)));z$explicitSubstitutionCount<-z$explicitSubstitutionCount+(s$exerciseState[[id]]$substitutionCount%||%0);z$mostRecentExerciseId<-id;fs[[f$familyId]]<-z}};s$familyState<-fs}
  s$provenance$relationshipSchemaVersion<-if(is.null(relationships))NULL else relationships$schemaVersion;s
}

# Keep nativeCycle fields as object members.  The original partial R helper
# placed the view in an unnamed list member, which made all downstream target
# comparisons silently see zero coverage.
.analyze_plan_partial <- analyze_plan
analyze_plan <- function(plan,database) {
  z<-.analyze_plan_partial(plan,database);n<-z$nativeCycle;view<-n[[2L]];z$nativeCycle<-c(list(periodDays=n$periodDays),view,list(exposureFrequency=n$exposureFrequency));z$exposureFrequency<-n$exposureFrequency;z
}
.evaluate_plan_partial <- evaluate_plan
evaluate_plan <- function(plan,db,profile=NULL,target=NULL,relationships=NULL) {z<-.evaluate_plan_partial(plan,db,profile,target,relationships);if(!length(z$exerciseCounts))z$exerciseCounts<-setNames(list(),character());if(!length(z$families$targets))z$families$targets<-setNames(list(),character());if(!length(z$frequency))z$frequency<-setNames(list(),character());if(!length(z$movementPatterns))z$movementPatterns<-setNames(list(),character());for(k in names(z$movementPatterns%||%list())){raw<-target$movementPatterns[[k]]%||%list();r<-list(min=raw$minimumSets%||%NULL,target=raw$targetSets%||%NULL,max=raw$maximumSets%||%NULL);row<-z$movementPatterns[[k]][setdiff(names(z$movementPatterns[[k]]),c("minimum","target","maximum","state"))];z$movementPatterns[[k]]<-c(row,list(minimum=r$min,target=r$target,maximum=r$max,state=.range_state(z$movementPatterns[[k]]$plannedSets,r)))};for(k in names(z$families$targets%||%list())){raw<-target$families[[k]]%||%list();r<-list(min=raw$minimumSets%||%NULL,target=raw$targetSets%||%NULL,max=raw$maximumSets%||%NULL);row<-z$families$targets[[k]][setdiff(names(z$families$targets[[k]]),c("minimum","target","maximum","state"))];z$families$targets[[k]]<-c(row,list(minimum=r$min,target=r$target,maximum=r$max,state=.range_state(z$families$targets[[k]]$plannedSets,r)))};z$provenance<-c(z$provenance,list(durationPolicy=if(!is.null(profile$availability$minutesPerSession))"duration-estimation-v1"else NULL));if(!is.null(profile$availability$minutesPerSession))z$warnings<-sort(unique(c(z$warnings,"duration estimation is not evaluated by duration-estimation-v1 because PLAN rest/transition inputs are not complete")));gaps<-c(Filter(function(x)identical(x$state,"below_minimum"),z$muscleCoverage%||%list()),Filter(function(x)identical(x$state,"below_minimum"),z$frequency%||%list()),Filter(function(x)identical(x$state,"below_minimum"),z$movementPatterns%||%list()),Filter(function(x)identical(x$state,"below_minimum"),z$families$targets%||%list()));z$summary$targetGaps<-length(gaps);z$summary$meetsTargetMinimums<-!length(gaps);if(!length(z$constraints$violations)&&isTRUE(z$coverageCompleteness$mappedFraction>=1))z$summary$evaluationStatus<-if(length(gaps))"valid_with_target_gaps"else"valid";z}
.family_coverage_partial <- .family_coverage
.family_coverage <- function(plan,rel) {z<-.family_coverage_partial(plan,rel);for(id in names(z)){used<-list();for(eid in z[[id]]$exerciseIds){row<-Filter(function(x)identical(x$relationship,"member_of_family"),rel$.by_exercise[[eid]]%||%list());dims<-if(length(row))row[[1L]]$dimensions%||%list()else list();z[[id]]$variantDimensions[[eid]]<-dims;for(k in names(dims))used[[k]]<-I(sort(unique(c(used[[k]]%||%character(),.strings(dims[[k]]))))) };z[[id]]$variantDimensionsUsed<-used};z}
.evaluate_plan_preferences <- evaluate_plan
evaluate_plan <- function(plan,db,profile=NULL,target=NULL,relationships=NULL) {z<-.evaluate_plan_preferences(plan,db,profile,target,relationships);p<-.doc(profile);if(!is.null(p)){prefs<-p$exercisePreferences%||%list();pe<-.strings(prefs$preferredExerciseIds);ae<-.strings(prefs$avoidedExerciseIds);pf<-.strings(prefs$preferredFamilyIds);af<-.strings(prefs$avoidedFamilyIds);findings<-list();for(s in plan$sessions%||%list())for(rx in s$exercises%||%list()){f<-family_for(relationships,rx$exerciseId);fid<-if(is.null(f))NULL else f$familyId;addf<-function(typ,vals,field=NULL){if(length(rx$exerciseId)&&rx$exerciseId%in%vals)findings[[length(findings)+1L]]<<-list(type=typ,exerciseId=rx$exerciseId,prescriptionId=rx$prescriptionId,sessionId=s$planSessionId);if(!is.null(field)&&!is.null(fid)&&fid%in%vals)findings[[length(findings)+1L]]<<-list(type=typ,exerciseId=rx$exerciseId,familyId=fid,prescriptionId=rx$prescriptionId,sessionId=s$planSessionId)};addf("preferred_exercise_used",pe);addf("avoided_exercise_used",ae);addf("preferred_family_used",pf,"family");addf("avoided_family_used",af,"family")};if(length(findings))findings<-findings[order(vapply(findings,function(x)x$type,character(1)),vapply(findings,function(x)x$exerciseId%||%x$familyId,character(1)),vapply(findings,function(x)x$sessionId%||%"",character(1)),vapply(findings,function(x)x$prescriptionId%||%"",character(1)))];used<-function(ids,typ){sort(unique(vapply(Filter(function(x)identical(x$type,typ)&&!is.null(x$exerciseId),findings),function(x)x$exerciseId,character(1))))};usedf<-function(ids,typ){sort(unique(vapply(Filter(function(x)identical(x$type,typ)&&!is.null(x$familyId),findings),function(x)x$familyId,character(1))))};z$preferences<-list(preferredExercisesUsed=used(pe,"preferred_exercise_used"),preferredFamiliesUsed=usedf(pf,"preferred_family_used"),avoidedExercisesUsed=used(ae,"avoided_exercise_used"),avoidedFamiliesUsed=usedf(af,"avoided_family_used"),findings=findings);z$summary$softPreferenceWarnings<-length(findings)};z}

