adapt_plan <- function(profile,target,current_plan,history,db,policy="general-adaptive-v1",relationships=NULL,training_state=NULL,as_of=NULL,options=list()) {
  z<-.adapt_plan_partial(profile,target,current_plan,history,db,policy,relationships,training_state,as_of,options);state<-.doc(z$trainingState);cur<-.doc(current_plan);proposed<-z$proposedPlan;changes<-list();decisions<-z$decisions%||%list()
  for(d in decisions) if(identical(d$decisionType,"increase_load")){before<-NULL;after<-NULL;for(s in cur$sessions%||%list())for(rx in s$exercises%||%list())if(identical(rx$prescriptionId,d$prescriptionId)){before<-.deepcopy(rx);after<-.deepcopy(rx);after$load<-d$after$load};if(!is.null(before))changes[[length(changes)+1L]]<-list(type="LOAD_CHANGED",prescriptionId=before$prescriptionId,exerciseId=before$exerciseId,before=before,after=after,reasonCodes="PROGRESSION_CRITERIA_MET",decisionIds=list(paste0("decision-increase_load-",before$prescriptionId)))}
  ah<-state$adherenceState%||%list();subhist<-ah$substitutionHistoryByPrescription%||%list();for(s in cur$sessions%||%list())for(rx in s$exercises%||%list()){opts<-subhist[[rx$prescriptionId]]%||%list();if(!length(opts))next;valid<-Filter(function(x)(x$count%||%0)>=2,opts);if(!length(valid))next;replacement<-names(valid)[order(-vapply(valid,function(x)x$count%||%0,numeric(1)),names(valid))[1L]];if(is.null(proposed)){proposed<-.deepcopy(cur);proposed$revisionId<-options$revisionId%||%if(grepl("^r[0-9]+$",cur$revisionId))paste0("r",as.integer(sub("^r","",cur$revisionId))+1L)else paste0(cur$revisionId,"-adaptive-1")};for(ps_i in seq_along(proposed$sessions))for(pr_i in seq_along(proposed$sessions[[ps_i]]$exercises%||%list()))if(identical(proposed$sessions[[ps_i]]$exercises[[pr_i]]$prescriptionId,rx$prescriptionId)){before<-.deepcopy(proposed$sessions[[ps_i]]$exercises[[pr_i]]);proposed$sessions[[ps_i]]$exercises[[pr_i]]$exerciseId<-replacement;proposed$sessions[[ps_i]]$exercises[[pr_i]]$exerciseName<-.exercise(db,replacement)$name%||%.exercise(db,replacement)$source$name%||%before$exerciseName;changes[[length(changes)+1L]]<-list(type="EXERCISE_SUBSTITUTED",prescriptionId=rx$prescriptionId,exerciseId=rx$exerciseId,before=before,after=proposed$sessions[[ps_i]]$exercises[[pr_i]],reasonCodes="REPEATED_SUBSTITUTION",decisionIds=list(paste0("decision-substitute_exercise-",rx$prescriptionId)));decisions[[length(decisions)+1L]]<-list(schemaVersion="0.1.0",decisionId=paste0("decision-substitute_exercise-",rx$prescriptionId),decisionType="substitute_exercise",policyId=policy,policyVersion="1.0.0",planId=cur$planId,revisionId=cur$revisionId,prescriptionId=rx$prescriptionId,exerciseId=rx$exerciseId,before=list(exerciseId=rx$exerciseId),after=list(exerciseId=replacement),reasonCodes="REPEATED_SUBSTITUTION",evidence=list(substitutionCount=valid[[replacement]]$count),provenance=state$provenance%||%list())}}
  if(is.null(proposed)&&!isTRUE(z$currentEvaluation$summary$satisfiesHardConstraints)){g<-generate_plan(profile,target,db,policy="full-body-general-v1",training_state=state,relationships=relationships,current_plan=cur,options=list(planId=cur$planId,revisionId=options$revisionId%||%"r2",name=cur$name));if(!is.null(g$plan)){proposed<-g$plan;changes[[length(changes)+1L]]<-list(type="PLAN_REGENERATED",reasonCodes="PLAN_REGENERATION_REQUIRED",decisionIds=list("decision-regenerate"));decisions[[length(decisions)+1L]]<-list(schemaVersion="0.1.0",decisionId="decision-regenerate",decisionType="regenerate_plan",policyId=policy,policyVersion="1.0.0",planId=cur$planId,revisionId=cur$revisionId,before=list(),after=list(),reasonCodes="PLAN_REGENERATION_REQUIRED",evidence=list(),provenance=state$provenance%||%list())}}
  if(!is.null(proposed)){z$proposedPlan<-proposed;z$proposedEvaluation<-evaluate_plan(proposed,db,profile,target,relationships);z$status<-"revision_proposed"};z$changes<-changes;z$decisions<-decisions;z
}

