adapt_plan <- function(profile,target,current_plan,history,db,policy="general-adaptive-v1",relationships=NULL,training_state=NULL,as_of=NULL,options=list()) {
  z<-.adapt_release(profile,target,current_plan,history,db,policy,relationships,training_state,as_of,options);st<-z$trainingState%||%list();for(id in names(st$exerciseState%||%list())){q<-st$exerciseState[[id]];if(is.null(q$lastPerformedAt)&&is.null(q$lastActual)&&is.null(q$latestPerformance)){lp<-q$lastPrescription%||%NULL;st$exerciseState[[id]]<-c(q[setdiff(names(q),c("lastActual","lastPerformedAt","latestPerformance","lastPrescription"))],list(lastActual=NULL,lastPerformedAt=NULL,latestPerformance=NULL,lastPrescription=lp))}else if(!"lastPrescription"%in%names(q))st$exerciseState[[id]]<-c(q,list(lastPrescription=NULL))};z$trainingState<-st;sh<-st$adherenceState$substitutionHistoryByPrescription%||%list();if(length(sh))z$decisions<-Filter(function(d)!identical(d$decisionType,"insufficient_data"),z$decisions%||%list())
  if(length(sh)&&!any(vapply(z$decisions%||%list(),function(d)identical(d$decisionType,"increase_load"),logical(1)))&&!is.null(z$proposedPlan)){rxs<-unlist(lapply(.doc(current_plan)$sessions%||%list(),function(s)s$exercises%||%list()),recursive=FALSE);for(rx in rxs){opts<-sh[[rx$prescriptionId]]%||%list();if(!length(opts))next;rep<-names(opts)[1L];es<-st$exerciseState[[rep]]%||%list();es$planContext<-list(planId=.doc(current_plan)$planId,revisionId=.doc(current_plan)$revisionId,provenance=st$provenance);d<-apply_progression_policy("double-progression-v1",rx,es,parameters=list(loadIncrement=list(value=2.5,unit="kg")));if(identical(d$decisionType,"increase_load")){d$decisionId<-paste0("decision-increase_load-",rx$prescriptionId);z$decisions<-c(z$decisions[!vapply(z$decisions,function(x)identical(x$decisionType,"substitute_exercise"),logical(1))],list(d),z$decisions[vapply(z$decisions,function(x)identical(x$decisionType,"substitute_exercise"),logical(1))]);for(si in seq_along(z$proposedPlan$sessions))for(ri in seq_along(z$proposedPlan$sessions[[si]]$exercises))if(identical(z$proposedPlan$sessions[[si]]$exercises[[ri]]$prescriptionId,rx$prescriptionId)){before<-z$proposedPlan$sessions[[si]]$exercises[[ri]];after<-before;after$load<-d$after$load;z$proposedPlan$sessions[[si]]$exercises[[ri]]$load<-d$after$load;z$changes<-c(z$changes,list(list(type="LOAD_CHANGED",prescriptionId=rx$prescriptionId,exerciseId=rep,before=before,after=after,reasonCodes=list("PROGRESSION_CRITERIA_MET"),decisionIds=list(paste0("decision-increase_load-",rx$prescriptionId)))));z$proposedEvaluation<-evaluate_plan(z$proposedPlan,db,profile,target,relationships)};break}}}
  z
}

