derive_training_state <- function(history,db,as_of,window="last_28_days",relationships=NULL,target=NULL,timezone="UTC") {s<-.derive_training_state_engine(history,db,as_of,window,relationships,target,timezone);h<-.doc(history);s<-.state_rows(s,h,db,timezone,target);s$provenance<-.state_provenance(s,h,db,relationships,target,as_of,timezone);s$asOf<-s$provenance$asOf;s$historyWindow<-s$provenance$historyWindow;s}

.adapt_canonical <- adapt_plan
adapt_plan <- function(profile,target,current_plan,history,db,policy="general-adaptive-v1",relationships=NULL,training_state=NULL,as_of=NULL,options=list()) {
  z<-.adapt_canonical(profile,target,current_plan,history,db,policy,relationships,training_state,as_of,options)
  if(!is.null(z$proposedPlan))for(d in z$decisions%||%list())if(identical(d$decisionType,"increase_load"))for(si in seq_along(z$proposedPlan$sessions%||%list()))for(ri in seq_along(z$proposedPlan$sessions[[si]]$exercises%||%list()))if(identical(z$proposedPlan$sessions[[si]]$exercises[[ri]]$prescriptionId,d$prescriptionId))z$proposedPlan$sessions[[si]]$exercises[[ri]]$load<-d$after$load
  if(!is.null(z$proposedPlan)&&!is.null(z$proposedEvaluation))z$proposedEvaluation<-evaluate_plan(z$proposedPlan,db,profile,target,relationships)
  for(i in seq_along(z$changes%||%list())) if(identical(z$changes[[i]]$type,"LOAD_CHANGED")&&!is.null(z$changes[[i]]$after$exerciseId)) z$changes[[i]]$exerciseId<-z$changes[[i]]$after$exerciseId
  for(i in seq_along(z$decisions%||%list())) { d<-z$decisions[[i]]; if(is.null(d$decisionId))d$decisionId<-paste0("decision-",d$decisionType,"-",d$prescriptionId);if(identical(d$decisionType,"increase_load")&&!is.null(z$proposedPlan))for(ps in z$proposedPlan$sessions%||%list())for(rx in ps$exercises%||%list())if(identical(rx$prescriptionId,d$prescriptionId))d$exerciseId<-rx$exerciseId;if(identical(d$decisionType,"substitute_exercise")){sh<-z$trainingState$adherenceState$substitutionHistoryByPrescription[[d$prescriptionId]]%||%list();rep<-names(sh)[1L];if(length(rep)){q<-sh[[rep]];d$evidence<-list(prescriptionId=d$prescriptionId,replacementExerciseId=rep,sessionIds=q$sessionIds,timestamps=q$timestamps,substitutionCount=q$count)}};if(identical(d$decisionType,"hold")&&identical(.strings(d$reasonCodes),"REPEATEDLY_SKIPPED")){n<-z$trainingState$adherenceState$skippedPrescriptionCounts[[d$prescriptionId]]%||%d$evidence$skippedPrescriptionCount;d$evidence<-list(skippedPrescriptionCount=n)};z$decisions[[i]]<-d }
  if(any(vapply(z$changes%||%list(),function(x)identical(x$type,"PLAN_REGENERATED"),logical(1))))z$status<-"regeneration_proposed"
  z
}

.evaluate_plan_canonical <- evaluate_plan
evaluate_plan <- function(plan,db,profile=NULL,target=NULL,relationships=NULL) {z<-.evaluate_plan_canonical(plan,db,profile,target,relationships);if(!length(z$families$coverage))z$families$coverage<-.empty_object();z}

.derive_state_canonical <- derive_training_state
derive_training_state <- function(history,db,as_of,window="last_28_days",relationships=NULL,target=NULL,timezone="UTC") {
  s<-.derive_state_canonical(history,db,as_of,window,relationships,target,timezone)
  if(!is.null(target))for(m in names(s$muscleState%||%list())){tr<-target$muscles[[m]];if(!is.null(tr)&&!is.null(.range(tr)$max)&&s$muscleState[[m]]$effectiveSets>=.range(tr)$max)s$muscleState[[m]]$targetState<-"within_range_below_target"}
  h<-.doc(history);start<-as.Date(s$historyWindow$start);end<-as.Date(s$historyWindow$end);for(id in names(s$exerciseState)){obs<-list();for(w in h$workouts%||%list()){q<-.parse_time(w$startTime,timezone);if(is.na(q)||as.Date(q,tz=timezone)<start||as.Date(q,tz=timezone)>end||q>.parse_time(as_of,timezone))next;for(e in w$exercises%||%list())if(identical(e$exerciseId,id))obs[[length(obs)+1L]]<-list(w=w,e=e)};if(!length(obs)){st<-s$exerciseState[[id]];st$lastPerformedAt<-NULL;st$lastActual<-NULL;st$latestPerformance<-NULL;st$recentPerformances<-list();st$recentSessionCount<-0L;st$recentCompletedSetCount<-0L;st$recentReps<-list();st$recentLoads<-list();st$recentRPE<-list();st$recentRIR<-list();st$recentSetTypes<-list();st$substitutionCount<-0L;st$unplannedCount<-0L;s$exerciseState[[id]]<-st}}
  sc<-list();for(x in s$adherenceState$exercisePrescriptionAdherence%||%list())if(identical(x$match_status,"substitution")&&!is.null(x$prescription_id))sc[[x$prescription_id]]<-(sc[[x$prescription_id]]%||%0L)+1L;s$adherenceState$substitutionCountsByPrescription<-if(length(sc))sc else .empty_object();s
}

