apply_progression_policy <- function(policy,prescription,exercise_state,db=NULL,parameters=list()) {z<-.progression_canonical(policy,prescription,exercise_state,db,parameters);if(!length(z$provenance))z$provenance<-.empty_object();z}

.derive_chars <- derive_training_state
derive_training_state <- function(history,db,as_of,window="last_28_days",relationships=NULL,target=NULL,timezone="UTC") {s<-.derive_chars(history,db,as_of,window,relationships,target,timezone);if(!is.null(target)){extra<-unique(unlist(lapply(names(target$muscles%||%list()),function(x)strsplit(x,"",fixed=TRUE)[[1L]])));for(m in extra)if(is.null(s$muscleState[[m]]))s$muscleState[[m]]<-list(muscleId=m,directSets=0,indirectSets=0,stabilizerSets=0,effectiveSets=0,exposures=0,mappedFraction=1,plannedVsActual=list(planned=0,actual=0),targetState="not_targeted")};s}

